window.CR_DADOS=window.CR_DADOS||{};CR_DADOS["2026-10"]={"2026-10-31":[{"id":"e345f2dbc4733c","t":"DJI quer que seus drones corporativos voltem ao ar em 25 segundos","r":"A DJI está trazendo a troca automatizada de baterias para sua linha de drones em uma caixa, e está fazendo isso com um retorno notavelmente rápido. Seu recém-anunciado DJI Dock 4 pode substituir uma bateria de drone descarregada por uma totalmente carregada em apenas 25 segundos, permitindo que a aeronave retorne ao ar sem esperar por um a bordo…","u":"https://dronedj.com/2026/10/30/dji-dock-4-matrice-5td-drone/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/10/dji-dock-4-matrice-5td-drone.jpg?quality=82&strip=all&w=1200","d":"2026-10-31T03:29-03:00","c":["drones","logistica"],"l":0,"to":"DJI wants its enterprise drones back in the air in 25 seconds","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O maior ponto de discussão sobre o DJI Dock 4 não é necessariamente o drone que ele abriga. É o que acontece quando aquele drone chega em casa."},{"id":"cdee227d1e4f52","t":"FCC suspende restrição de décadas às operações celulares de drones","r":"Durante anos, uma restrição de décadas concebida para impedir que os telemóveis interferissem nas redes móveis terrestres também impediu as operações dos drones. A Comissão Federal de Comunicações (FCC) decidiu agora que é hora de seguir em frente. mais…","u":"https://dronedj.com/2026/10/30/fcc-drone-cellular-spectrum/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/04/fcc-american-drone-dominance.jpg?quality=82&strip=all&w=1200","d":"2026-10-31T03:51-03:00","c":["drones"],"l":0,"to":"FCC lifts decades-old restriction on drone cellular operations","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"Esta decisão faz parte de um esforço mais amplo da FCC para fortalecer a posição da América na indústria global de drones."}],"2026-10-30":[{"id":"bf12c379974b4d","t":"Vídeo sexta-feira: Spot Plays para mostrar sua manipulação de corpo inteiro","r":"Video Friday é sua seleção semanal de vídeos incríveis de robótica, coletados por seus amigos do IEEE Spectrum Robotics. Também publicamos um calendário semanal dos próximos eventos de robótica para os próximos meses. Por favor, envie-nos seus eventos para inclusão. CoRL 2026: 9–12 de novembro de 2026, AUSTIN Humanoids 2026: 6–9 de dezembro de 2026…","u":"https://spectrum.ieee.org/video-friday-whole-body-manipulation","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/colorful-boston-dynamics-robot-dog-plays-with-a-tire-on-an-outdoor-basketball-court-while-someone-with-a-hockey-stick-interferes.webp?id=68558917&width=980","d":"2026-10-30T13:30-03:00","c":["competicoes","humanoides"],"l":0,"to":"Video Friday: Spot Plays to Show Its Whole-Body Manipulation","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Sua seleção semanal de vídeos incríveis de robôs"},{"id":"4093e094ffa327","t":"Robot Talk Episódio 168 – Avanços na robótica com eletrônica inovadora, com Zlatka Stoeva","r":"Claire conversou com Zlatka Stoeva da DZP Technologies sobre eletrônicos impressos flexíveis, extensíveis e macios para robôs hábeis. Zlatka Stoeva é fundadora e diretora administrativa da DZP Technologies, uma empresa com sede em Cambridge especializada em materiais avançados e novas formas de eletrônica. A formação de Zlatka é…","u":"https://robohub.org/robot-talk-episode-168-advancing-robotics-with-novel-electronics-with-zlatka-stoeva/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Zlatka-Stoeva-425x239.jpg","d":"2026-10-30T10:33-03:00","c":["geral"],"l":0,"to":"Robot Talk Episode 168 – Advancing robotics with novel electronics, with Zlatka Stoeva","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Claire conversou com Zlatka Stoeva da DZP Technologies sobre eletrônicos impressos flexíveis, extensíveis e macios para robôs hábeis. Zlatka Stoeva é fundadora e diretora administrativa da DZP Technologies, uma empresa com sede em Cambridge especializada em materiais avançados e novas formas de eletrônica. A formação de Zlatka é em química de materiais e ela desenvolveu materiais eletrônicos inovadores que estabeleceram as bases para o atual portfólio da empresa de eletrônicos flexíveis, extensíveis e macios. A DZP Technologies se aventurou na robótica durante um projeto financiado pela ARIA, focado em componentes eletrônicos impressos para robôs hábeis."},{"id":"abfc2d464ed106","t":"Lagartas blindadas oferecem aos designers de robôs lições sobre como cruzar vidros escorregadios","r":"Os animais têm sido uma das principais fontes de inspiração para pesquisadores de robótica. Isso ocorre porque eles dependem de mecanismos biológicos sofisticados e estratégias de locomoção que poderiam ser reproduzidas artificialmente em robôs para equipá-los com as capacidades desejadas.","u":"https://techxplore.com/news/2026-10-armored-caterpillars-robot-lessons-slippery.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/armored-caterpillars-o-2.jpg","d":"2026-10-30T11:40-03:00","c":["ia"],"l":0,"to":"Armored caterpillars offer robot designers lessons in crossing slippery glass","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"45fd290d29a06f","t":"Campo de recursos rápidos: o elo perdido entre câmeras de eventos e visão robótica","r":"Durante décadas, as câmeras de eventos, que emulam a retina biológica monitorando continuamente as mudanças na intensidade da luz, prometeram revolucionar a forma como os robôs percebem o mundo, permitindo-lhes reagir mais rapidamente e operar de forma mais confiável do que as câmeras convencionais permitem.","u":"https://techxplore.com/news/2026-10-fast-feature-field-link-event.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/the-missing-link-betwe.jpg","d":"2026-10-30T12:20-03:00","c":["geral"],"l":0,"to":"Fast Feature Field: The missing link between event cameras and robot vision","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"2cc9a057b610d2","t":"A mariposa robô desenvolve um sensor UV usando um sistema circulatório artificial","r":"Um robô em forma de mariposa usou um sistema circulatório artificial para fornecer blocos de construção químicos através de seu corpo e desenvolver um sensor de luz onde a luz ultravioleta incidia.","u":"https://techxplore.com/news/2026-10-robot-moth-uv-sensor-artificial.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/robot-moth-gained-an-e.jpg","d":"2026-10-30T14:00-03:00","c":["geral"],"l":0,"to":"Robot moth grows a UV sensor by using an artificial circulatory system","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"41c2227ec580f6","t":"UgCS 6.3 adiciona controle de acompanhamento de terreno para pesquisas LiDAR complexas com drones","r":"Planejar uma pesquisa com drones em centenas de hectares é uma coisa. Garantir que cada voo, configuração do sensor e manobra de calibração se encaixe no mesmo plano geral é outra. A SPH Engineering quer facilitar essa segunda parte com o UgCS 6.3, a atualização mais recente de seu software de planejamento de voo de drones. mais…","u":"https://dronedj.com/2026/10/29/lidar-drone-survey-dji-ugcs/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/10/ugcs-update-dji-drone-lidar-survey-terrain-follow.jpg?quality=82&strip=all&w=1207","d":"2026-10-30T03:43-03:00","c":["drones"],"l":0,"to":"UgCS 6.3 adds terrain-following control for complex drone LiDAR surveys","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"A SPH Engineering deseja facilitar seus grandes levantamentos LiDAR com UgCS 6.3, a atualização mais recente de seu software de planejamento de voo de drones."},{"id":"f475c067e9727a","t":"Rick Scott redobra as restrições aos drones DJI e Autel enquanto a FCC analisa os recursos","r":"O senador norte-americano Rick Scott está a reagir contra as tentativas da DJI e da Autel Robotics de contestar a sua colocação na lista coberta da Comissão Federal de Comunicações, argumentando que Washington passou anos a investigar os fabricantes chineses de drones e já chegou à conclusão certa sobre a segurança nacional. mais…","u":"https://dronedj.com/2026/10/29/rick-scott-dji-drone-fcc/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2025/12/dji-drone-ban-us-security-review-deadline-december-2025.jpg?quality=82&strip=all&w=1600","d":"2026-10-30T03:51-03:00","c":["drones"],"l":0,"to":"Rick Scott doubles down on DJI and Autel drone restrictions as FCC reviews appeals","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O senador dos EUA Rick Scott está resistindo às tentativas da DJI e da Autel Robotics de desafiar sua colocação na lista coberta da FCC."},{"id":"62373f3f48e14e","t":"Evite conversa fiada: faça conexões revolucionárias no TechCrunch Founder Summit com Braindate","r":"No TechCrunch Founder Summit 2026, que acontecerá em 4 de novembro na SoWa Power Station em Boston, a rede desenvolvida pelo Braindate foi projetada para tornar essas conversas mais fáceis de encontrar, sejam elas em reuniões individuais ou em pequenos grupos no local. Registre-se antes do início do evento para economizar até US$ 100 em seu passe, além de ganhar um segundo…","u":"https://techcrunch.com/2026/10/30/skip-the-small-talk-make-game-changing-connections-at-techcrunch-founder-summit-with-braindate/","f":"TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2025/03/Early-Stage-2024-networking-1.jpg?resize=1200,800","d":"2026-10-30T11:00-03:00","c":["competicoes"],"l":0,"to":"Skip the small talk: Make game-changing connections at TechCrunch Founder Summit with Braindate","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"No TechCrunch Founder Summit 2026, que acontecerá em 4 de novembro na SoWa Power Station em Boston, a rede desenvolvida pelo Braindate foi projetada para tornar essas conversas mais fáceis de encontrar, sejam elas em reuniões individuais ou em pequenos grupos no local. A única maneira de fazer essas conexões revolucionárias é no Founder Summit. O Founder Summit Networking Lounge oferece aos participantes a oportunidade de agendar Braindates individuais ou em pequenos grupos ao longo do dia.\nO Founder Summit é construído em torno de perguntas que os fundadores já estão fazendo: Como saber quando você está pronto para escalar? O Founder Summit é intencionalmente menor e mais prático do que uma conferência massiva. TechCrunch Founder Summit 2026 acontecerá em 4 de novembro na SoWa Power Station em Boston. Obtenha seu passe do Founder Summit e resgate seu segundo ingresso grátis."}],"2026-10-29":[{"id":"b6d910ad7cf2c1","t":"AGIBOT apresenta Worken para medir o trabalho produtivo do robô no AGIBOT Innovation Day 2026","r":"AGIBOT revela sua plataforma de hardware integrada AHA3, modelo GO-3 Preview e WITA-Omni, lança formalmente G2 Max e Link-U OS 1.0 e destaca implantações no mundo real","u":"http://www.RoboticsTomorrow.com/news/2026/10/29/agibot-introduces-worken-to-measure-productive-robot-work-at-agibot-innovation-day-2026/27319","f":"RoboticsTomorrow.com News","s":"roboticstomorrow.com","i":"","d":"2026-10-29T10:07-03:00","c":["humanoides"],"l":0,"to":"AGIBOT Introduces Worken to Measure Productive Robot Work at AGIBOT Innovation Day 2026","lg":"en","esp":1,"p":5.4,"mx":9,"cr":3,"cv":"Robotics Tomorrow","rx":"AGIBOT revela sua plataforma de hardware integrada AHA3, modelo GO-3 Preview e WITA-Omni, lança formalmente G2 Max e Link-U OS 1.0 e destaca implementações no mundo real A AGIBOT apresentou hoje o Worken, uma estrutura proposta para medir o trabalho produtivo realizado por robôs em ambientes do mundo real, no AGIBOT Innovation Day 2026 em Xangai. A empresa estreou o GO-3 Preview, seu modelo de base de IA incorporada de próxima geração, apresentou seu modelo de interação omnimodal WITA-Omni e lançou o robô industrial G2 Max e o Link-U OS 1.0. Juntos, AHA3, AGILE, GO-3 Preview e WITA-Omni refletem o progresso da AGIBOT em arquitetura de hardware integrada, inteligência de locomoção, execução de tarefas e interação humano-robô. AGIBOT lança G2 Max e destaca implantações no mundo real A AGIBOT lançou o G2 Max, um robô industrial de serviço pesado projetado para aplicações de manufatura e logística."},{"id":"7b870dd7b313c6","t":"O ruído de entrega de drones está se tornando um problema. Zipline tem uma nova resposta","r":"A próxima grande melhoria na entrega de drones pode não ser entregas mais rápidas ou tempos de voo mais longos. Pode ser garantir que seus vizinhos mal percebam o drone trazendo seu pacote. mais…","u":"https://dronedj.com/2026/10/28/delivery-drone-noise-zipline-software/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/06/Zipline-drone-delivery-wonder-texas.jpg?quality=82&strip=all&w=1200","d":"2026-10-29T03:31-03:00","c":["entrega","drones"],"l":0,"to":"Drone delivery noise is becoming a problem. Zipline has a new answer","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"A mais recente atualização de engenharia da Zipline usa modelagem de som em tempo real para ajudar seus drones de entrega autônomos a voar de forma mais silenciosa."},{"id":"c5de748a53bd7e","t":"Seus drones industriais coletam dados. Percepto quer que a IA faça valer a pena","r":"As inspeções industriais de drones têm um problema de dados. Os drones podem capturar imagens detalhadas de quilômetros de linhas de energia, extensas instalações de petróleo e gás e equipamentos industriais de difícil acesso. Mas alguém ainda precisa examinar todas essas filmagens, identificar possíveis problemas e decidir quais deles precisam de atenção primeiro…","u":"https://dronedj.com/2026/10/28/percepto-axion-drone-inspection-ai/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/10/percepto-axion-drone-inspection-AI.jpg?quality=82&strip=all&w=1205","d":"2026-10-29T03:49-03:00","c":["drones","inspecao"],"l":0,"to":"Your industrial drones collect data. Percepto wants AI to make it count","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O software Percepto Axion traz análise de inspeção baseada em IA para frotas de drones, sensores e registros de inspeção existentes."},{"id":"90f17187580f72","t":"Electromate comemora 40 anos de excelência em engenharia e compromisso com a automação canadense","r":"Marcando quatro décadas de conhecimento técnico, parcerias confiáveis ​​e uma cultura que prioriza as pessoas nas indústrias de mecatrônica e robótica do Canadá.","u":"http://www.RoboticsTomorrow.com/news/2026/10/29/electromate-celebrates-40-years-of-engineering-excellence-and-commitment-to-canadian-automation/27320","f":"RoboticsTomorrow.com News","s":"roboticstomorrow.com","i":"","d":"2026-10-29T10:28-03:00","c":["negocios"],"l":0,"to":"Electromate Celebrates 40 Years of Engineering Excellence and Commitment to Canadian Automation","lg":"en","esp":1,"p":4.6,"mx":9,"cr":3,"cv":"Robotics Tomorrow","rx":"Marcando quatro décadas de conhecimento técnico, parcerias confiáveis ​​e uma cultura que prioriza as pessoas nas indústrias de mecatrônica e robótica do Canadá. VAUGHAN, ONTÁRIO, 1º de novembro de 2026 - Electromate Inc., um distribuidor canadense líder de controle de movimento de precisão, soluções mecatrônicas e robóticas, comemora orgulhosamente seu 40º aniversário, marcando quatro décadas ajudando engenheiros e fabricantes canadenses a resolver desafios complexos de automação. Quatro Décadas de Parcerias Confiáveis ​​O sucesso da Electromate foi construído em relacionamentos duradouros com clientes, fornecedores e funcionários. Através de parcerias com fabricantes líderes globais, a Electromate fornece soluções avançadas de automação, experiência em engenharia de aplicação e suporte técnico para ajudar os clientes a projetar e construir máquinas confiáveis ​​e de alto desempenho e sistemas complexos de automação e robótica."},{"id":"a33445f403b3c9","t":"Sistemas 6-DOF MagLev para embalagens avançadas introduzidos na SEMICON West 2026, novidade da PI","r":"Estágios lineares, rotativos e AFM de seis eixos levitados magneticamente proporcionam estabilidade nanométrica e correção de erros durante o processo para colagem, inspeção e metrologia","u":"http://www.RoboticsTomorrow.com/news/2026/10/29/6-dof-maglev-systems-for-advanced-packaging-introduced-at-semicon-west-2026-new-from-pi-/27321","f":"Robotics Tomorrow","s":"roboticstomorrow.com","i":"","d":"2026-10-29T10:31-03:00","c":["inspecao"],"l":0,"to":"6-DOF MagLev Systems for Advanced Packaging Introduced at SEMICON West 2026, new from PI","lg":"en","esp":1,"p":4.6,"cr":3,"cv":"Robotics Tomorrow","mx":9},{"id":"a14b0cce81bb63","t":"IMTS estende parceria com McCormick Place até 2034, reforçando impacto econômico de US$ 500 milhões em Chicago","r":"AMT – The Association For Manufacturing Technology and McCormick Place announce extended agreement for 2032 and 2034 shows alongside $101,000 investment in Chicago Public Schools STEM education.","u":"http://www.RoboticsTomorrow.com/news/2026/10/29/imts-extends-mccormick-place-partnership-through-2034-reinforcing-500m-economic-impact-on-chicago/27323","f":"RoboticsTomorrow.com News","s":"roboticstomorrow.com","i":"","d":"2026-10-29T17:27-03:00","c":["negocios","educacao","industriais"],"l":0,"to":"IMTS Extends McCormick Place Partnership Through 2034, Reinforcing $500M Economic Impact on Chicago","lg":"en","esp":1,"p":4.6,"mx":9,"cr":3,"cv":"Robotics Tomorrow","rx":"AMT – A Association For Manufacturing Technology e McCormick Place anunciam um acordo estendido para programas de 2032 e 2034, juntamente com um investimento de US$ 101.000 na educação STEM das Escolas Públicas de Chicago. Chicago (29 de outubro de 2026) — AMT - The Association For Manufacturing Technology, produtora do IMTS - The International Manufacturing Technology Show, e McCormick Place anunciaram hoje uma extensão de sua parceria de longa data, garantindo Chicago como sede do principal evento da AMT, IMTS, até 2034. Em parceria com a Haas Automation e a Gene Haas Foundation, a IMTS está contribuindo com US$ 101.000 para as Escolas Públicas de Chicago (CPS) para apoiar a educação STEM programas que apresentam aos alunos tecnologias avançadas de fabricação e oportunidades de carreira."},{"id":"8238768b37f504","t":"Usinagem de peças grandes transformada com robótica de alta precisão","r":"For some applications, investing in a CNC machine results in paying for unnecessary capability. Fives High Precision Machines (Fives HPM) provides a different and more effective approach with the Liné Machines RoboTDM, a high-precision robotic machining solution that brings direct milling, trimming, and drilling to…","u":"http://www.RoboticsTomorrow.com/news/2026/10/29/large-part-machining-transformed-with-high-precision-robotics/27324","f":"RoboticsTomorrow.com News","s":"roboticstomorrow.com","i":"","d":"2026-10-29T19:38-03:00","c":["inspecao"],"l":0,"to":"Large-Part Machining Transformed with High-Precision Robotics","lg":"en","esp":1,"p":4.6,"mx":9,"cr":3,"cv":"Robotics Tomorrow","rx":"Para algumas aplicações, investir em uma máquina CNC resulta no pagamento de recursos desnecessários. Fives High Precision Machines (Fives HPM) oferece uma abordagem diferente e mais eficaz com o Liné Machines RoboTDM, uma solução de usinagem robótica de alta precisão que traz fresamento, corte e perfuração diretos para peças grandes. A usinagem de componentes grandes requer uma grande máquina-ferramenta CNC, certo? Para aplicações onde tolerâncias até aproximadamente 0,1 mm são aceitáveis, o Liné Machines RoboTDM oferece uma alternativa altamente atrativa. Em última análise, ao atingir um nível de precisão suficiente para uma variedade de aplicações de peças grandes, o RoboTDM oferece aos fabricantes outra opção entre a robótica convencional e o custo de grandes máquinas-ferramentas CNC."},{"id":"d269098e8249d1","t":"Um robô de entrega ultrapassou o sinal vermelho, bateu um ônibus e saiu do local do acidente: nove feridos","r":"","u":"https://news.google.?oc=5","f":"Infobae","s":"infobae.com","i":"","d":"2026-10-29T04:00-03:00","c":["entrega"],"l":0,"to":"Un robot de reparto pasó un semáforo en rojo, chocó un autobús y abandonó la escena del accidente: nueve heridos","lg":"es","p":3.5,"cr":3,"cv":"Infobae"}],"2026-10-28":[{"id":"e9585d5badb725","t":"Competindo no RoboCup@Home e ganhando o prêmio de melhor artigo de 2026: entrevista com Raphael Memmesheimer","r":"Robô da equipe NimbRo em ação durante a competição RoboCup@Home na RoboCup 2026. Raphael lidera a equipe. Raphael Memmesheimer tem competido com sucesso na liga RoboCup@Home, vencendo a competição RoboCup@Home cinco vezes. Ele e seus colegas ganharam o prêmio de melhor artigo na RoboCup 2026 por seu trabalho…","u":"https://robohub.org/competing-in-robocuphome-and-winning-the-2026-best-paper-award-an-interview-with-raphael-memmesheimer/","f":"Robohub","s":"robohub.org","i":"https://aihub.org/wp-content/uploads/2026/10/2026_07_04_RoboCup_Home_NimbRo_Grasping_2-scaled.jpg","d":"2026-10-28T06:07-03:00","c":["competicoes"],"l":0,"to":"Competing in RoboCup@Home and winning the 2026 best paper award: an interview with Raphael Memmesheimer","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"O robô da equipe NimbRo em ação durante a competição RoboCup@Home no RoboCup 2026. Raphael Memmesheimer competiu com sucesso na liga RoboCup@Home vencendo a competição RoboCup@Home cinco vezes. Ele e seus colegas ganharam o prêmio de melhor artigo no RoboCup 2026 por seu trabalho “Efficient Image Annotation via Semi-Supervised Object Segmentation with Label Propagation”. Conversamos com o Raphael para saber mais sobre essa pesquisa, sua história com a RoboCup e os desafios da competição @Home.\nSempre volto às competições de robôs porque este é um dos raros lugares onde você pode avaliar robôs em um ambiente real e ter uma competição real. Nosso artigo basicamente nos ajuda a gerar esses dados de forma muito eficiente, para que os robôs possam aprender mais rapidamente modelos para os objetos envolvidos nesta competição."},{"id":"067c9dcc2a61f5","t":"Robô voador inspirado em insetos se recupera após colisões","r":"Insetos voadores, como moscas-das-frutas, abelhas, libélulas e mosquitos, podem disparar por espaços estreitos e sobreviver a colisões com vários objetos. Em contraste, muitos robôs voadores caem, sofrem danos ou até quebram quando atingem superfícies ou objetos próximos.","u":"https://techxplore.com/news/2026-10-insect-flying-robot-collisions.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/an-insect-inspired-fly-1.jpg","d":"2026-10-28T08:40-03:00","c":["geral"],"l":0,"to":"Insect-inspired flying robot bounces back after collisions","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"19950921145ba7","t":"Uma nova almofada flexível para os pés permite que este robô saltitante de uma perna vá aonde poucos robôs chegaram antes","r":"Uma equipe de pesquisadores de engenharia da Universidade de Toronto desenvolveu uma almofada flexível para os pés do \"Hopcopter\" - um robô saltitante de uma perna que eles desenvolveram - melhorando significativamente seu desempenho em areia, gelo e outros terrenos difíceis.","u":"https://techxplore.com/news/2026-10-flexible-foot-pad-enables-legged.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/a-new-flexible-foot-pa-1.jpg","d":"2026-10-28T12:40-03:00","c":["ia"],"l":0,"to":"A new flexible foot pad enables this one-legged, hopping robot to go where few robots have gone before","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"f9847c46651283","t":"Controles de drone autoajustáveis ​​podem proporcionar um vôo em formação mais suave","r":"Um novo método para controlar grupos de drones, tecnicamente conhecidos como veículos aéreos não tripulados (UAVs), poderia tornar o voo em formação mais suave e reduzir o consumo de energia e o desgaste mecânico, de acordo com uma pesquisa publicada no International Journal of Systems, Control and Communications. O trabalho combina lógica difusa…","u":"https://techxplore.com/news/2026-10-adjusting-drone-smoother-formation-flying.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/many-drones.jpg","d":"2026-10-28T17:40-03:00","c":["drones"],"l":0,"to":"Self-adjusting drone controls could make for smoother formation flying","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"ca340d318d264b","t":"Possui um drone DJI Flip? Verifique essas configurações após a atualização mais recente","r":"Se o seu DJI Flip estiver na bolsa da câmera esperando pela próxima viagem, há uma pequena atualização de manutenção que vale a pena instalar antes da decolagem. DJI lançou um novo firmware para seu drone de câmera compacto, juntando-se a uma onda mais ampla de atualizações de limpeza lançadas em toda a linha de drones de consumo da empresa. mais…","u":"https://dronedj.com/2026/10/27/new-update-dji-flip-drone/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/07/dji-flip-drone-discount-2026.jpg?quality=82&strip=all&w=1200","d":"2026-10-28T03:42-03:00","c":["drones"],"l":0,"to":"Own a DJI Flip drone? Check these settings after the latest update","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O lançamento do Flip faz parte de um lote mais amplo de atualizações de firmware da DJI que inclui vários drones populares de consumo."},{"id":"47a32af3414239","t":"DJI Modify 1.7.0 adiciona novas maneiras de refinar modelos 3D de drones","r":"DJI Modify é mais do que uma ferramenta para limpar modelos 3D gerados por drones. Ele foi projetado para ajudar os profissionais de mapeamento a transformar resultados brutos de reconstrução em resultados polidos e utilizáveis, seja isso significando reparar um modelo de construção, melhorar texturas de superfície ou preparar dados 3D para fluxos de trabalho posteriores. mais…","u":"https://dronedj.com/2026/10/27/dji-modify-update-drone-mapping/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2024/01/dji-modify-3d-drone-modeling-software.jpg?quality=82&strip=all&w=1214","d":"2026-10-28T03:55-03:00","c":["drones"],"l":0,"to":"DJI Modify 1.7.0 adds new ways to refine drone 3D models","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"Com a versão 1.7.0 do Modify, a DJI está adicionando mais maneiras de trabalhar diretamente com modelos de malha 3D, juntamente com melhorias na visualização de nuvens de pontos e inspeção de terreno."}],"2026-10-27":[{"id":"6016a3f712c28a","t":"Drones Autel EVO Lite 640T e 6K recebem uma nova atualização","r":"Autel Robotics tem uma nova atualização de firmware para sua série EVO Lite Enterprise, dando aos profissionais outro motivo para conferir uma linha de drones compactos projetados para trabalhos que vão muito além da fotografia aérea. mais…","u":"https://dronedj.com/2026/10/26/evo-lite-firmware-autel-enterprise/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/10/autel-new-firmware-evo-lite-enterprise-640t-6k-drone.jpg?quality=82&strip=all&w=1200","d":"2026-10-27T03:50-03:00","c":["drones"],"l":1,"to":"Autel EVO Lite 640T and 6K drones get a new update","lg":"en","p":10.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O EVO Lite Enterprise não é simplesmente um drone de câmera de consumo com um rótulo diferente. Autel oferece duas versões e ambas recebem uma nova atualização de firmware."},{"id":"1698e31ea5a4be","t":"As funções de segurança do seu robô já funcionam. E se a entrada mentir?","r":"Este artigo foi trazido a você por VicOne. Um robô móvel diminui a velocidade para alguém em um corredor. Um braço colaborativo facilita seu movimento conforme um trabalhador se aproxima. Um humanóide faz uma pausa para deixar uma pessoa passar. Cada resposta depende de informações sobre o robô ou seu entorno: uma leitura de distância, uma estimativa de posição ou uma parada…","u":"https://spectrum.ieee.org/ai-robot-safety-cybersecurity-vicone","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/humanoid-robot-and-robot-dog-meet-a-woman-on-a-sunny-terrace-at-sunset.jpg?id=68002098&width=980","d":"2026-10-27T13:14-03:00","c":["humanoides","logistica"],"l":0,"to":"Your Robot’s Safety Functions Already Work. What If the Input Lies?","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"VicOne é uma empresa de segurança cibernética de IA física que protege veículos e robôs contra ameaças cibernéticas que podem alterar o comportamento e comprometer a segurança. Um robô pode seguir suas regras de segurança e ainda agir com base nas informações manipuladas. Veja o que isso significa para a segurança dos robôs e como as equipes podem fortalecer seus testes e evidências."},{"id":"f4409b756f65ca","t":"A pele eletrônica exibe instantaneamente o toque como luz","r":"“Seu toque me ilumina” parece uma afirmação figurativa bastante romântica, não é? Bem, não mais. Pesquisadores da Universidade Nacional de Cingapura (NUS) desenvolveram uma pele eletrônica ultrafina e flexível que se ilumina quando tocada, revelando exatamente onde a pressão está sendo aplicada e quanto, tipo…","u":"https://newatlas.com/robotics/eluminator-electronic-skin-displays-touch-as-light/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/7c76dd1/2147483647/strip/true/crop/4274x2849+0+0/resize/1440x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F69%2Fd2%2Fa2f6fbed46e08c884f1b7cad5665%2F1021249.jpeg","d":"2026-10-27T06:14-03:00","c":["ia"],"l":0,"to":"Electronic skin instantly displays touch as light","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Pesquisadores da Universidade Nacional de Cingapura (NUS) desenvolveram uma pele eletrônica ultrafina e flexível que se ilumina quando tocada, revelando exatamente onde a pressão está sendo aplicada e a quantidade, como uma espécie de pele com tela. Ele funciona convertendo a pressão física diretamente em padrões visíveis de luz, permitindo que os usuários vejam a forma e a distribuição do contato quase instantaneamente, sem a necessidade de um display separado ou processamento complexo de sinais.\nPrimeiro, em vez de depender de sistemas separados de detecção de pressão e de exibição visual, os pesquisadores combinaram ambas as funções dentro da própria pele eletrônica, usando uma estrutura contínua sensível à pressão que produz luz diretamente em resposta à pressão."},{"id":"e3d20134e95520","t":"A pele artificial ajuda os robôs a agarrar a grafite do lápis e a se afastar das agulhas","r":"Os pesquisadores cobriram os dedos robóticos com uma nova pele artificial que permite que a mão segure a frágil grafite do lápis e se afaste da agulha antes que ela perfure a cobertura. Ambas as ações dependem de mais do que sensores sensíveis. O robô também deve receber e interpretar seus sinais com rapidez suficiente para responder.","u":"https://techxplore.com/news/2026-10-artificial-skin-robots-grasp-pencil.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/artificial-skin-helps.jpg","d":"2026-10-27T08:10-03:00","c":["ia","negocios"],"l":0,"to":"Artificial skin helps robots grasp pencil lead and pull away from needles","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3}],"2026-10-26":[{"id":"ad9d4a8e654241","t":"IA detecta sinais “invisíveis” de câncer de pâncreas anos antes do diagnóstico","r":"Um novo e poderoso sistema de IA poderia ajudar os médicos a detectar o câncer de pâncreas anos antes de ele se tornar visível nos exames convencionais. A tecnologia, chamada REDMOD, identificou sinais de alerta ocultos em média 475 dias antes do diagnóstico e foi quase duas vezes mais sensível que radiologistas experientes. Ao detectar problemas relacionados ao câncer…","u":"https://www.sciencedaily.com/releases/2026/10/261024222031.htm","f":"ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/pancreatic-cancer-male-anatomy.webp","d":"2026-10-26T06:25-03:00","c":["medicina"],"l":0,"to":"AI detects “invisible” signs of pancreatic cancer years before diagnosis","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"Um modelo de inteligência artificial chamado REDMOD pode identificar alterações extremamente sutis no tecido pancreático que podem sinalizar câncer muito antes de a doença se tornar visível aos médicos ou à tecnologia de imagem convencional. De acordo com uma pesquisa publicada online na revista Gut, o sistema pode detectar sinais precoces de adenocarcinoma ductal pancreático, o tipo mais comum de câncer de pâncreas.\nOs investigadores acreditam que esta tecnologia pode ajudar a transformar a deteção do cancro do pâncreas, identificando a doença numa fase muito mais precoce (fase 0), quando o tratamento tem maior probabilidade de sucesso. O REDMOD identificou com sucesso assinaturas de imagem sutis associadas ao câncer de pâncreas, em média 475 dias antes dos pacientes receberem seus diagnósticos clínicos."},{"id":"6dbfd111d82bc5","t":"Robôs na sociedade, nos negócios e na cultura: setembro de 2026","r":"Uma mão robótica ambulante, de Fingers as Legs: Learning Self-Supported Locomotion and Manipulation with an Anthropomorphic Hand, Amirhossein Kazemipour, Hehui Zheng, Robert Katzschmann. Por Emmet Cole Em nossa série mensal, apresentamos uma seleção de histórias de robótica da sociedade, negócios, pesquisa e cultura, à medida que…","u":"https://robohub.org/robots-in-society-business-and-culture-september-2026/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/robot_hand-1024x797.jpeg","d":"2026-10-26T07:17-03:00","c":["geral"],"l":0,"to":"Robots in society, business and culture: September 2026","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Mais de cinco milhões de robôs industriais estão agora operando em fábricas em todo o mundo, de acordo com o recém-lançado relatório World Robotics 2026 da Federação Internacional de Robótica. As fábricas instalaram mais de 600.000 robôs industriais durante 2025, um aumento de 11% em relação ao ano anterior. Suas fábricas instalaram 354 mil robôs, representando 59% do total global.\nA Índia instalou quase 10.500 robôs, um aumento de 15%. Um estudo publicado no International Journal of Human-Computer Interaction examinou se as percepções de justiça podem reduzir o conflito entre pessoas e robôs de segurança. Os resultados provêm de pesquisas controladas sobre interação humano-robô, portanto não devem ser tratados como evidências de robôs exercendo autoridade em ambientes de policiamento operacional."},{"id":"964f79ef596d2e","t":"Cão robótico controlado por computador alimentado por células sanguíneas humanas","r":"Uma start-up já usou um computador biológico para jogar Pong e agora a empresa afirma que a tecnologia pode ser usada para controlar robôs","u":"https://www.newscientist.com/article/2594537-robotic-dog-controlled-with-a-computer-powered-by-human-blood-cells/?utm_campaign=RSS|NSNS&utm_content=robotics&utm_medium=RSS&utm_source=NSNS","f":"New Scientist","s":"newscientist.com","i":"https://www.newscientist.com/wp-content/uploads/2026/10/SEI_318277800.jpg","d":"2026-10-26T11:00-03:00","c":["quadrupedes"],"l":0,"to":"Robotic dog controlled with a computer powered by human blood cells","lg":"en","esp":1,"p":5.1,"cr":2,"cv":"New Scientist","mx":1,"rx":"Células vivas foram usadas para criar um computador biológico que pode controlar os movimentos de um cão robótico. Os seus criadores afirmam que a utilização de células para replicar as redes neurais digitais de modelos de IA como o ChatGPT – que são modelados em cérebros biológicos – poderia criar computadores mais eficientes e adaptáveis. A start-up Cortical Labs criou e comercializou um computador biológico chamado CL1, que pode ser treinado para navegar em direção a um alvo em um ambiente 2D simulado.\nA Cortical Labs já utilizou células vivas para realizar cálculos: em 2021, mostrou que sua tecnologia poderia jogar o jogo de computador Pong. Brett Kagan, do Cortical Labs, diz que as células usadas nos computadores CL1 são criadas a partir de células-tronco geradas a partir de sangue doado por pessoas que deram seu consentimento."},{"id":"7d08e45e15653a","t":"O drone DJI Avata 360 ficou ainda melhor na captura de fotos cinematográficas","r":"Um drone que captura tudo ao seu redor ficou ainda melhor para decidir para onde voar em seguida. O Avata 360 da DJI adquiriu voo de waypoint, controles de zoom para rastreamento de assunto e suporte para o controlador RC Pro 2 em uma nova atualização de firmware, dando aos cineastas aéreos mais maneiras de tirar a foto sem depender inteiramente de…","u":"https://dronedj.com/2026/10/25/dji-avata-360-new-firmware/","f":"DroneDJ","s":"dronedj.com","i":"https://dronedj.com/wp-content/uploads/sites/2/2026/10/dji-avata-360-drone-new-firmware-update-2026.jpg?quality=82&strip=all&w=1200","d":"2026-10-26T03:57-03:00","c":["drones"],"l":0,"to":"DJI Avata 360 drone just got better at capturing cinematic shots","lg":"en","p":4.8,"cr":3,"cv":"DroneDJ","mx":1,"rx":"O novo firmware do drone DJI Avata 360 adiciona voo de waypoint para rotas planejadas, controles de zoom para FocusTrack e suporte para o controlador RC Pro 2."}],"2026-10-25":[{"id":"3307993e5122d2","t":"Besouro-robô controlado pelos dedos ostenta músculos artificiais e feedback bidirecional","r":"Os insetos sempre foram uma fonte de inspiração para engenheiros de robótica. Eles são pequenos, ágeis e podem se espremer em espaços onde as pessoas não conseguem. Esses robôs são muito úteis para exploração espacial, inspeção de equipamentos industriais e até mesmo operações de busca e salvamento. Para determinados fins, os pesquisadores recorrem…","u":"https://newatlas.com/robotics/beetlebot-robotic-beetle/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/0cb18bb/2147483647/strip/true/crop/2484x1656+0+0/resize/1440x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2Fec%2Fb1%2Fbb235e3247b0bc75532eed511057%2Ffigure2.jpeg","d":"2026-10-25T06:03-03:00","c":["microrrobos","inspecao","resgate"],"l":0,"to":"Finger-controlled robo beetle sports artificial muscles & two-way feedback","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Para determinados fins, os investigadores transformam insectos reais em ciborgues – o que levanta algumas preocupações éticas – por isso, por vezes, constroem robôs inspirados em besouros a partir do zero. Uma equipe do Instituto Avançado de Ciência e Tecnologia da Coreia (KAIST) está trabalhando em um novo robô chamado BeetleBot, e sua aparência nem é a coisa mais interessante sobre ele. Para projetar o BeetleBot, os pesquisadores se inspiraram em um besouro real chamado Mecynorrhina torquata – um dos maiores insetos do mundo, nativo do Congo, Camarões e Uganda.\nEmbora apenas esses músculos precisem ser aquecidos, e não todo o robô, tal mecanismo ainda requer bastante energia para gerar esse calor. O robô envia informações visuais da câmera para o humano em tempo real, o humano responde com um determinado gesto, o robô segue o comando e envia feedback imediato."}],"2026-10-24":[{"id":"b15ac292bb30a0","t":"Sistema vestível captura dados de atividade humana para treinamento de robôs","r":"Robôs humanóides, sistemas robóticos com formato corporal semelhante ao dos humanos, poderiam realizar diversas tarefas manuais cotidianas. Para completar com sucesso estas tarefas, no entanto, os robôs devem ser capazes de coordenar de forma confiável os seus movimentos, postura e como tocam ou agarram diferentes objetos.","u":"https://techxplore.com/news/2026-10-wearable-captures-human-robot.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/a-wearable-system-coul.jpg","d":"2026-10-24T13:00-03:00","c":["humanoides"],"l":0,"to":"Wearable system captures human activity data for robot training","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"e6d4ea57d9aa11","t":"Robô subaquático aproveita a biomimética para movimentos naturais","r":"Explorar o mundo subaquático requer robôs que possam se mover tão naturalmente quanto os peixes e, idealmente, se misturar tanto quanto possível. É exatamente nisso que um grupo de pesquisa da Universidade Estadual da Carolina do Norte vem trabalhando. Continue lendo Categoria: Robótica, Engenharia Tags: North Carolina State University, Biomimética…","u":"https://newatlas.com/robotics/feather-star-underwater-robot/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/edfba16/2147483647/strip/true/crop/1448x965+0+0/resize/1440x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F68%2F19%2F2008336948509ad112e43375b98a%2Ffeather-star-in-turquoise-waters.jpeg","d":"2026-10-24T23:03-03:00","c":["subaquaticos"],"l":0,"to":"Subaquatic robot leverages biomimetics for natural movement","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Explorar o mundo subaquático requer robôs que possam se mover tão naturalmente quanto os peixes e, idealmente, se misturar tanto quanto possível. Há alguns anos, a mesma equipe projetou um robô aquático inspirado em uma arraia manta. Mas o novo robô pode manobrar em três dimensões usando alguns membros elásticos e apenas dois atuadores. Seu design faz parte do trabalho, permitindo que o robô se mova em três modos diferentes.\nO robô estrela de penas usa um princípio semelhante. À medida que as asas se recuperam, o robô pode descer. Os pesquisadores esperam que o robô possa abrir novas possibilidades para a exploração subaquática e que possa ser usado para diversas aplicações: desde carregar câmeras e levantar objetos até trabalhar ao lado de outros robôs aquáticos."}],"2026-10-23":[{"id":"f900d559464db3","t":"Sexta-feira de vídeo: Robô quadrúpede resolve sozinho o cubo gigante de Rubik","r":"Video Friday é sua seleção semanal de vídeos incríveis de robótica, coletados por seus amigos do IEEE Spectrum Robotics. Também publicamos um calendário semanal dos próximos eventos de robótica para os próximos meses. Por favor, envie-nos seus eventos para inclusão. CoRL 2026: 9–12 de novembro de 2026, AUSTIN Humanoids 2026: 6–9 de dezembro de 2026…","u":"https://spectrum.ieee.org/video-friday-rubiks-cube-robot","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/red-quadruped-robot-facing-a-large-rubik-s-cube-on-an-outdoor-tiled-surface.png?id=68512950&width=980","d":"2026-10-23T12:30-03:00","c":["quadrupedes","competicoes","humanoides"],"l":0,"to":"Video Friday: Quadruped Robot Solves Giant Rubik’s Cube by Itself","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Sua seleção semanal de vídeos incríveis de robôs"},{"id":"31295dfc3e917a","t":"Um pequeno defeito num cristal revela uma grande surpresa quântica","r":"Os pesquisadores resolveram um desafio de longa data na compreensão de como pequenos defeitos em materiais como diamante e carboneto de silício se comportam quando expostos à luz. Seu novo método computacional revelou um mecanismo de perda de energia surpreendentemente importante no carboneto de silício que os cientistas haviam subestimado anteriormente. O…","u":"https://www.sciencedaily.com/releases/2026/10/261022081302.htm","f":"Robotics Research News -- ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/galli-group-diamonds.webp","d":"2026-10-23T07:22-03:00","c":["ia"],"l":0,"to":"A tiny defect in a crystal reveals a big quantum surprise","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"Quando a luz atinge uma pequena imperfeição dentro de um material como o diamante ou o carboneto de silício, ela pode transferir energia para os elétrons e empurrá-los para um estado excitado. Essas imperfeições, conhecidas como defeitos de spin, podem se tornar blocos de construção valiosos para futuras tecnologias quânticas, incluindo sensores quânticos. \"Este processo de conversão interna não é relevante apenas para defeitos de spin - também está relacionado a processos de interesse para tecnologias de energia, \"disse Giulia Galli, Professora de Estrutura Eletrônica e Simulações da Família Liew na UChicago PME e no Departamento de Química e autor sênior do estudo.\nEntretanto, os cientistas estão a expandir a sua abordagem para investigar defeitos de spin no silício, bem como em materiais utilizados em tecnologias energéticas onde a conversão interna influencia a forma como a energia é transferida ou perdida."},{"id":"d9f200af0b9db9","t":"Cientistas do MIT constroem um pequeno robô que nada usando células musculares vivas","r":"Os engenheiros do MIT construíram um robô nadador fino como papel, alimentado por células musculares vivas que respondem a flashes de luz, permitindo-lhe nadar e navegar na água. A descoberta pode abrir caminho para pequenos robôs biológicos autocuráveis, capazes de explorar ambientes frágeis que as máquinas comuns não conseguem com segurança…","u":"https://www.sciencedaily.com/releases/2026/10/261022081308.htm","f":"Robotics Research News -- ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/soft-robot-that-can-flap-through-water.webp","d":"2026-10-23T07:33-03:00","c":["ia","microrrobos"],"l":0,"to":"MIT scientists build a tiny robot that swims using living muscle cells","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"Pesquisadores do MIT demonstraram que uma única camada de células musculares vivas cuidadosamente projetada pode gerar força suficiente para impulsionar um minúsculo robô para frente. Os engenheiros desenvolveram um robô nadador extremamente fino que usa tecido muscular vivo para mover suas nadadeiras. Ao direcionar a luz para qualquer uma das nadadeiras, os pesquisadores podem desencadear contrações musculares que fazem a nadadeira bater e empurrar o robô através da água.\nO dispositivo representa a primeira demonstração de um robô bidimensional muito fino que pode se mover de um lugar para outro usando tecido muscular vivo. Pulsos repetidos de luz estimularam a contração das células, fortalecendo o tecido muscular antes de ser incorporado ao robô nadador. Com a estrutura do gel otimizada e as células musculares fortalecidas, os pesquisadores montaram seu aparelho de natação."},{"id":"2ca1fedc75e81c","t":"Robot Talk Episódio 167 – Automatizando a construção, com Jan Petrš","r":"Claire conversou com Jan Petrš da École Polytechnique Fédérale de Lausanne (EPFL) e da Déploya Robotics sobre novos projetos de robôs para construção e arquitetura. Jan Petrš é roboticista, arquiteto e empresário que trabalha na intersecção entre robótica e construção. Atualmente é cofundador da Déploya…","u":"https://robohub.org/robot-talk-episode-167-automating-construction-with-jan-petrs/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Jan-Petrs_preferred-403x425.jpg","d":"2026-10-23T08:43-03:00","c":["construcao"],"l":0,"to":"Robot Talk Episode 167 – Automating construction, with Jan Petrš","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Claire conversou com Jan Petrš da École Polytechnique Fédérale de Lausanne (EPFL) e da Déploya Robotics sobre novos projetos de robôs para construção e arquitetura. Jan Petrš é roboticista, arquiteto e empresário que trabalha na interseção entre robótica e construção. Atualmente é cofundador da Déploya Robotics, uma spin-off da EPFL que desenvolve sistemas robóticos implantáveis ​​para instalação automatizada de fachadas. Anteriormente, foi pesquisador de pós-doutorado no Laboratório de Sistemas Inteligentes da EPFL, onde se concentrou em robótica de tensegridade. A sua investigação de doutoramento na Universidade Técnica Checa concentrou-se no desenvolvimento de um sistema robótico que combina robótica reconfigurável e suave para aplicações arquitetónicas e de construção."},{"id":"8a0fa786e4609c","t":"Braços robóticos flexíveis aprendem a prever seu próximo movimento","r":"Um braço robótico que se dobra como a tromba de um elefante pode escorregar em espaços apertados e manusear objetos frágeis. Controlá-lo é mais difícil porque sua curvatura suave torna difícil prever seu próximo movimento. Os pesquisadores desenvolveram agora um método que mantém as previsões do computador sobre o movimento do braço no caminho certo, mesmo quando o braço se move…","u":"https://techxplore.com/news/2026-10-flexible-robot-arms.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/flexible-robot-arms-le.jpg","d":"2026-10-23T18:00-03:00","c":["industriais"],"l":0,"to":"Flexible robot arms learn to predict their next move","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3}],"2026-10-22":[{"id":"2203bd1a772ab1","t":"Ex-líder científico da OpenAI lança Warp Science para automatizar laboratórios úmidos com robôs","r":"Usando câmeras e luvas com sensores, os químicos humanos da startup treinarão robôs para realizar diversas tarefas de laboratório.","u":"https://techcrunch.com/2026/10/22/former-openai-science-lead-launches-warp-science-to-automate-wet-labs-with-robots/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2016/10/4528869007_4484c3d401_b-1.jpg?w=1024","d":"2026-10-22T15:38-03:00","c":["ia","negocios"],"l":1,"to":"Former OpenAI science lead launches Warp Science to automate wet labs with robots","lg":"en","esp":1,"p":10.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"O ex-líder científico da OpenAI, Kevin Weil, lançou a Warp Sciences, uma nova startup de IA focada na automatização do trabalho de laboratório para descoberta de medicamentos. A empresa, que treina robôs para fabricar e testar compostos promissores identificados por pesquisadores, arrecadou US$ 215 milhões com uma avaliação de US$ 865 milhões, segundo Weil, que anunciou a inicialização e o financiamento do X. A rodada foi liderada pela Lightspeed, com a participação de IVP, Mayfield, Lux Capital, Premji Invest e Menlo Ventures.\nCom a Warp Sciences, Weil espera reestruturar esse trabalho e isolar todo o processo de desenvolvimento de medicamentos dos riscos geopolíticos da cadeia de abastecimento. Usando câmeras e luvas com sensores, os químicos humanos da startup treinarão robôs para realizar diversas tarefas de laboratório. Ao automatizar o trabalho de laboratório úmido, a Warp Sciences pretende acelerar a descoberta de medicamentos usando robôs que possam operar 24 horas por dia."},{"id":"21b52c943dc916","t":"‘Eu consideraria substituir um dos meus filhos’: Taika Waititi sobre crianças robôs, seu medidor de queijo e Klara e o Sol","r":"O diretor transformou o aclamado romance de Kazuo Ishiguro sobre uma adolescente doente e seu amigo robô problemático em um filme instigante. O que a dupla acha que esta história diz sobre tecnologia, amor e tristeza? Nos bastidores do festival de cinema de Londres, um grupo de jovens influenciadores discutem suas…","u":"https://www.theguardian.com/film/2026/oct/22/taika-waititi-kazuo-ishiguro-robot-friend-klara-and-the-sun","f":"The Guardian","s":"theguardian.com","i":"https://i.guim.co.uk/img/media/6cf2d328019eb962c7aad15131750c0e940da690/437_80_1110_888/master/1110.jpg?width=140&quality=85&auto=format&fit=max&s=c1904e249a5e882031b1babd4a394123","d":"2026-10-22T01:00-03:00","c":["educacao"],"l":0,"to":"‘I’d consider replacing one of my children’: Taika Waititi on robot kids, his cheese-o-meter and Klara and the Sun","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"The Guardian","mx":1,"rx":"O diretor transformou o aclamado romance de Kazuo Ishiguro sobre uma adolescente doente e seu amigo robô problemático em um filme instigante. O que a dupla acha que esta história diz sobre tecnologia, amor e tristeza? E os jovens influenciadores adoram Klara and the Sun – a adaptação de Waititi do aclamado romance de Kazuo Ishiguro – enquanto a maioria dos críticos mais velhos discorda veemente e violentamente. Em parte, é sobre isso que o filme trata.\nVocê faz o filme porque ama o livro. Klara e o Sol é uma história de amor, mas também trata de isolamento: a distância entre as pessoas; os limites da compreensão. É o meu filme do ano.”"},{"id":"d4ad264bd770c5","t":"Músculos de rato desenvolvidos em laboratório permitem que pequenos robôs saltem, nadem, andem e agarrem","r":"O tecido muscular esquelético desenvolvido em laboratório pode se contrair, mas o movimento costuma ser tão leve que quase não é visível. Isto representa um problema para robôs biohíbridos projetados para se moverem usando músculos vivos. Investigadores da ETH Zurique demonstraram agora que não é apenas a quantidade de tecido muscular que importa, mas acima de tudo como…","u":"https://techxplore.com/news/2026-10-lab-grown-mouse-muscles-enable.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/researchers-develop-mu.jpg","d":"2026-10-22T16:40-03:00","c":["ia","microrrobos"],"l":0,"to":"Lab-grown mouse muscles enable tiny robots to jump, swim, walk and grasp","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3}],"2026-10-21":[{"id":"429537805d74ae","t":"Robôs com rodas, voadores e de seis pernas permanecem no caminho certo com novo método de aprendizagem","r":"É importante para um robô não apenas aprender uma tarefa de maneira otimizada, mas também completá-la sem sair dos trilhos das expectativas razoáveis. Até agora, os roboticistas poderiam ter um ou outro. Pesquisadores de engenharia aeroespacial da Grainger College of Engineering, University of Illinois Urbana-Champaign, combinaram…","u":"https://techxplore.com/news/2026-10-wheeled-flying-legged-robots-stay.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/new-method-for-guarant.jpg","d":"2026-10-21T16:20-03:00","c":["quadrupedes"],"l":1,"to":"Wheeled, flying and six-legged robots stay on track with new learning method","lg":"en","esp":1,"p":12.4,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"2c9536723835ab","t":"Tesla supera projeções de lucros depois que Musk apresenta plano de fusão da SpaceX","r":"Musk diz que “há muito mérito” em uma possível fusão que exigiria a aprovação de 50% de todos os acionistas da Tesla, mas se recusou a entrar em detalhes. Os investidores estavam prestando muita atenção à divulgação dos lucros do terceiro trimestre da Tesla na tarde de quarta-feira, depois que o presidente-executivo Elon Musk apresentou a ideia de fundir o carro…","u":"https://www.theguardian.com/technology/2026/oct/21/elon-musk-tesla-spacex","f":"The Guardian","s":"theguardian.com","i":"https://i.guim.co.uk/img/media/5079e04428f0108241397eee4e3383a1344455f5/436_0_4565_3655/master/4565.jpg?width=140&quality=85&auto=format&fit=max&s=645b2152a14156592f81a8cc071672a4","d":"2026-10-21T20:03-03:00","c":["competicoes"],"l":0,"to":"Tesla beats earnings projections after Musk floats SpaceX merger plan","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"The Guardian","mx":1,"rx":"Musk diz que “há muito mérito” em uma possível fusão que exigiria a aprovação de 50% de todos os acionistas da Tesla, mas se recusou a entrar em detalhes. Os investidores estavam prestando muita atenção à divulgação dos lucros do terceiro trimestre da Tesla na tarde de quarta-feira, depois que o presidente-executivo Elon Musk apresentou a ideia de fundir a empresa automobilística com sua empresa de foguetes e IA, a SpaceX.\n“Com relação a uma potencial fusão com a SpaceX, acho que disse tudo o que deveria ser dito ontem”, disse Musk, o CEO de ambas as empresas, na teleconferência de resultados da Tesla. Numa teleconferência com investidores da SpaceX na terça-feira, Musk disse que seria uma “boa ideia” combinar as duas empresas e que “há muito mérito” que viria com isso. Na semana passada, Musk revelou o carro esportivo elétrico da empresa, o Roadster 2, que, segundo ele, usa tecnologia da SpaceX para “basicamente voar como um foguete”."},{"id":"bfb51e6eac2f70","t":"As pessoas estão tomando um medicamento para perda de peso não aprovado. IA encontrou algo surpreendente","r":"Pesquisadores analisando quase 150.000 postagens do Reddit descobriram relatos de sintomas inesperados vinculados por usuários a versões não aprovadas de retatrutida, incluindo aumento do apetite, distúrbios do sono e frequência cardíaca elevada. As descobertas diferem dos resultados dos ensaios clínicos e destacam como a IA pode ajudar a identificar potenciais…","u":"https://www.sciencedaily.com/releases/2026/10/261020085018.htm","f":"Robotics Research News -- ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/happy-young-woman-with-pink-donuts.webp","d":"2026-10-21T23:37-03:00","c":["ia"],"l":0,"to":"People are taking an unapproved weight-loss drug. AI found something surprising","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"O medicamento, retatrutida, pertence a uma nova geração de medicamentos GLP-1 desenvolvidos para ajudar a regular o apetite e o peso corporal. Pesquisadores da Universidade da Pensilvânia analisaram quase 150 mil postagens e comentários do Reddit de aproximadamente 40 mil usuários para investigar essas contas. Os utilizadores do Reddit representam uma população muito diferente dos participantes dos ensaios clínicos, e as suas contas não conseguem estabelecer se o medicamento causou os sintomas que descreveram.\n“Não podemos dizer que a retatrutida esteja causando esses sintomas, ou mesmo que os usuários do Reddit estejam realmente tomando retatrutida genuína, uma vez que a droga não está disponível legalmente e as formulações do mercado paralelo variam”, diz Lyle Ungar, professor do CIS e coautor do estudo. Mas entre os usuários do Reddit que relataram tomar retatrutida não aprovada, o padrão parecia diferente.","cur":1},{"id":"c4ee3f30eef45f","t":"Tesla inicia produção de robôs Optimus na Califórnia enquanto lucro cai 43%","r":"A receita da Tesla permaneceu estável e suas despesas dispararam à medida que ela pressionava o acelerador em seus robôs Optimus, IA e direção autônoma.","u":"https://techcrunch.com/2026/10/21/tesla-stars-optimus-robot-production-in-california-as-profit-falls-43/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/04/tesla-opitmus-Getty.jpg?resize=1200,800","d":"2026-10-21T17:33-03:00","c":["humanoides"],"l":0,"to":"Tesla starts Optimus robot production in California as profit falls 43%","lg":"en","esp":1,"p":5.1,"cr":2,"cv":"TechCrunch","mx":1,"rx":"A Tesla iniciou a produção de seu robô humanóide Optimus em sua fábrica em Fremont, Califórnia, em um espaço de fabricação antes dedicado à fabricação de veículos elétricos, anunciou a empresa na quarta-feira. O CEO da Tesla, Elon Musk, disse em uma teleconferência que considera esta “produção inicial” e que a rampa será lenta e “um tanto acidentada porque é um produto radicalmente novo”. Mesmo assim, ele afirmou que a Tesla será capaz de fabricar 20.000 deles por semana até o final de 2027.\nAs receitas da Tesla permaneceram estáveis e as suas despesas dispararam à medida que pressionou o acelerador nos seus robôs Optimus, IA e condução autónoma. A Tesla viu um declínio anual de 16% na receita de seu negócio de armazenamento de energia solar e de energia, para US$ 2,8 bilhões, culpa que atribuiu a reembolsos de clientes relacionados a tarifas."}],"2026-10-20":[{"id":"87711daf743243","t":"Prêmio ACM SIGAI Agentes Autônomos 2027 aberto para indicações","r":"São solicitadas indicações para o Prêmio de Pesquisa de Agentes Autônomos ACM SIGAI 2027. Este prêmio é concedido pela excelência em pesquisas na área de agentes autônomos. Pretende-se reconhecer investigadores em agentes autónomos cujo trabalho atual seja uma influência importante na área. O prêmio é um prêmio oficial da ACM…","u":"https://robohub.org/acm-sigai-autonomous-agents-award-2027-open-for-nominations/","f":"Robohub","s":"robohub.org","i":"https://aihub.org/wp-content/uploads/2022/07/acmsigai-logo.png","d":"2026-10-20T07:37-03:00","c":["geral"],"l":0,"to":"ACM SIGAI Autonomous Agents Award 2027 open for nominations","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"São solicitadas indicações para o Prêmio de Pesquisa de Agentes Autônomos ACM SIGAI 2027. Este prêmio é concedido pela excelência em pesquisas na área de agentes autônomos. Pretende-se reconhecer investigadores em agentes autónomos cujo trabalho atual seja uma influência importante na área. O prêmio é um prêmio oficial da ACM, financiado por uma doação criada pela ACM SIGAI a partir dos rendimentos de conferências anteriores de Agentes Autônomos. O ganhador do prêmio receberá um prêmio monetário e um certificado, e será convidado a apresentar uma palestra plenária na conferência AAMAS 2027.\nAs indicações devem ser feitas preenchendo este formulário do Google e devem consistir em uma breve declaração (<1 página) que enfatize não apenas as contribuições de pesquisa que o indivíduo fez que merecem o prêmio, mas também como o trabalho atual do indivíduo é uma influência importante na área."},{"id":"535b2e4e9386d7","t":"Palavras secretas podem tornar perigosos os robôs movidos a IA","r":"Grandes modelos de linguagem (LLMs), como ChatGPT da OpenAI, Claude da Anthropic e Google Gemini, estão sendo cada vez mais usados ​​para ajudar robôs a realizar tarefas, mas e se os LLMs pudessem ser explorados para transformar robôs úteis em robôs prejudiciais?","u":"https://techxplore.com/news/2026-10-secret-trigger-words-ai-powered.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/secret-trigger-words-c.jpg","d":"2026-10-20T17:40-03:00","c":["geral"],"l":0,"to":"Secret trigger words could make AI-powered robots dangerous","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"15705003f60bff","t":"Eka vale US$ 1,45 bilhão graças a um modelo físico de IA que deixou especialistas delirantes","r":"A Eka Robotics pode ser o primeiro braço robótico realmente bom em pegar uma ampla variedade de objetos, e é tão suave e semelhante ao humano que está impressionando a indústria.","u":"https://techcrunch.com/2026/10/20/eka-is-worth-1-45-billion-thanks-to-a-physical-ai-model-that-has-experts-raving/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/10/Screenshot-2026-10-19-at-1.21.23-PM.png?resize=1200,974","d":"2026-10-20T10:00-03:00","c":["ia","industriais"],"l":0,"to":"Eka is worth $1.45B thanks to a physical AI model that has experts raving","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"Isso pode estar prestes a mudar, graças a uma arquitetura de manipulação construída pela Eka Robotics, que engloba uma pinça sensível à força e um novo tipo de modelo de aprendizagem profunda. Em uma era de demonstrações robóticas sem fim, as capacidades do Eka estão chocando os construtores de robôs veteranos. O robô Eka “foi capaz de se adaptar a um grande número de objetos diferentes sem retreinamento”, disse Hauser, acrescentando que também tinha um aspecto de “humanidade, uma humanidade assustadora que tentaria repetidamente se falhasse na primeira vez”.\nOutro roboticista, que pediu anonimato por causa de seu trabalho em um laboratório de fronteira, disse ao TechCrunch que ver o robô de Eka em ação foi uma experiência emocional, comparável a quando os robôs alcançaram pela primeira vez uma locomoção confiável com pernas, cinco a 10 anos atrás."},{"id":"2d379e8ffc916c","t":"Amulya Vishwanath, ex-Nvidia que virou VC: ‘A IA física está em sua era LEGO’","r":"É o momento que todos estão esperando – o momento ChatGPT para a robótica, explicou Amulya Vishwanath ao TechCrunch’s Equity.","u":"https://techcrunch.com/2026/10/20/ex-nvidia-turned-vc-amulya-vishwanath-physical-ai-is-in-its-lego-era/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/10/GettyImages-1404749040.jpg?resize=1200,675","d":"2026-10-20T13:20-03:00","c":["educacao","ia"],"l":0,"to":"Ex-Nvidia-turned-VC Amulya Vishwanath: ‘Physical AI is in its LEGO era’","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"É o momento que todos estão esperando – o momento ChatGPT para a robótica, explicou Amulya Vishwanath ao TechCrunch’s Equity. Ela é fundadora e sócia-gerente da Techable Ventures, uma empresa de capital de risco focada em IA física, que começou depois de passar quase sete anos como comerciante de produtos na Nvidia. “Muitas empresas e especialistas têm falado sobre o momento ChatGPT para a robótica”, disse ela, acrescentando que neste momento a indústria está mais na “era LEGO”.\n“Há muitos softwares básicos e blocos de construção para a robótica que estão sendo repensados ​​neste momento, e isso é muito importante para que a inovação cresça”, continuou ela. Este é um dos “fossos” de sua empresa, disse ela, ajudando a conectar os fundadores aos principais talentos para que possam permanecer competitivos agora, já que muitos talentos estão indo para grandes empresas como Anthropic e Nvidia."}],"2026-10-19":[{"id":"b657bbd1f782d9","t":"O robô que eu não esperava construir","r":"Agility Robotics, a empresa que fundei em meu laboratório de robótica na Oregon State University em 2015, acaba de lançar o Digit 5. Ele foi projetado para ser o primeiro robô humanóide que pode realizar trabalhos úteis em escala de forma segura e econômica, permitindo-nos trazer dezenas de milhares de trabalhadores humanóides para o mundo real…","u":"https://spectrum.ieee.org/agility-robotics-digit-5-redesign","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/author-jonathan-hurst-a-tall-slim-white-man-wearing-a-black-long-sleeve-shirt-and-dark-jeans-stands-next-to-his-digit-5-humano.jpg?id=68441166&width=980","d":"2026-10-19T10:00-03:00","c":["humanoides"],"l":0,"to":"The Robot I Didn’t Expect to Build","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"O autor e cofundador da Agility Robotics, Jonathan Hurst, ao lado de seu novo robô humanóide Digit 5. Agility Robotics, a empresa que fundei em meu laboratório de robótica na Oregon State University em 2015, acaba de lançar o Digit 5. O dígito 5 é o objetivo que a Agility vem trabalhando há mais de uma década. O Dígito 1, que adicionou um torso e braços às pernas de Cassie, foi nosso primeiro robô de manipulação móvel e mais um passo no caminho em direção a um produto que poderia realizar um trabalho útil para clientes comerciais.\nO Dígito 5 será o primeiro passo real da Agility em direção a um robô de uso geral. Pesando mais de 120 kg, o Digit 5 ​​é um enorme robô. Com o Digit 5, a Agility construiu um robô que será útil em nosso mundo."},{"id":"df1cd74f8c1816","t":"Alimentado por células musculares, um robô fino como papel nada em um labirinto aquático","r":"Os engenheiros do MIT desenvolveram um robô macio que pode atravessar a água em resposta a flashes de luz. Crédito da foto: Melanie Gonick, MIT. Por Jennifer Chu A natação pode exigir muitos músculos. Mas, como descobriram os engenheiros do MIT, mesmo uma única camada de células musculares pode passar pela água se for projetada corretamente. Em um artigo aparecendo…","u":"https://robohub.org/powered-by-muscle-cells-a-paper-thin-robot-swims-through-watery-maze/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/09/MIT-RoboMuscle-01-press_0.jpg","d":"2026-10-19T04:07-03:00","c":["ia","microrrobos"],"l":0,"to":"Powered by muscle cells, a paper-thin robot swims through watery maze","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Mas, como descobriram os engenheiros do MIT, mesmo uma única camada de células musculares pode passar pela água se for projetada corretamente. Em seu novo trabalho, a equipe do Raman Lab teve como objetivo maximizar os movimentos musculares para produzir mais força – o suficiente, digamos, para alimentar um robô nadador. Eles carimbaram um disco de gel com um padrão de sulcos concêntricos e radiais e depositaram células musculares vivas na superfície do gel.\nEm seu novo trabalho, a equipe teve como objetivo maximizar os movimentos musculares para produzir mais força – o suficiente, por exemplo, para alimentar um robô nadador. A equipe também variou a espessura do gel e descobriu que um filme de GelMa com meio milímetro de espessura oferecia um bom suporte para uma única camada de células musculares. Com as células bombeadas e o gel otimizado, a equipe projetou um robô fino de duas aletas, composto pelo gel, estampado em ambos os lados com ranhuras de fundo quadrado e revestido com células musculares."},{"id":"1d528d3cc018e3","t":"Das tocas de wombat à Arca de Noé: Robô se junta à busca","r":"A tecnologia desenvolvida por um engenheiro australiano para explorar tocas de wombat foi enviada ao leste de Türkiye para se juntar à busca pela Arca de Noé bíblica.","u":"https://techxplore.com/news/2026-10-wombat-burrows-noah-ark-robot.html","f":"Tech Xplore","s":"techxplore.com","i":"https://scx1.b-cdn.net/csz/news/tmb/2026/from-wombat-burrows-to-1.jpg","d":"2026-10-19T23:40-03:00","c":["geral"],"l":0,"to":"From wombat burrows to Noah's Ark: Robot joins search","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Tech Xplore","mx":3},{"id":"448617650f8a8e","t":"A Laplace Intelligence reúne robôs e carros autônomos antes que eles cheguem ao mundo real","r":"A Laplace Intelligence, spinout da Universidade de Michigan, usa agentes de IA e simulação interativa para testar robôs e veículos autônomos antes da implantação. A startup lucrativa está competindo no Startup Battlefield no TechCrunch Disrupt, de 13 a 15 de outubro em São Francisco.","u":"https://techcrunch.com/2026/10/19/laplace-intelligence-red-teams-robots-and-self-driving-cars-before-they-hit-the-real-world/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/07/GettyImages-2274650383.jpg?resize=1200,840","d":"2026-10-19T09:30-03:00","c":["autonomos","defesa"],"l":0,"to":"Laplace Intelligence red-teams robots and self-driving cars before they hit the real world","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"“Imagine se algo assim acontecesse no mundo físico”, disse Howie Sun, CEO e cofundador da Laplace Intelligence, ao TechCrunch. “Os agentes de IA estão migrando dos computadores para o mundo real e não queremos realmente que a IA física falhe no mundo real.” Laplace é uma das 20 startups competindo no Startup Battlefield 200, a competição de startups que acontece no TechCrunch Disrupt em São Francisco esta semana, de 13 a 15 de outubro.\n“Percebi que queria construir isso e transformá-lo em uma pesquisa puramente acadêmica em um produto que fosse útil no mundo real”, disse Sun. O objetivo é garantir que qualquer IA física – seja um robô, um veículo autônomo ou uma solução de cidade inteligente – esteja segura na simulação antes de ser implantada no mundo real."}],"2026-10-17":[{"id":"590172f5c7a4de","t":"Robô bioinspirado lança ar em águas remotas por meio de vela-asa transformada","r":"“Caia como uma semente de bordo, navegue como um barco” soa como um conselho do lendário boxeador peso-pesado Muhammad Ali. Na realidade, descreve uma nova plataforma robótica que os cientistas criaram para uma implantação rápida e a longo prazo para monitorizar águas remotas. Continue lendo Categoria: Robótica, Engenharia Tags: Transformável…","u":"https://newatlas.com/robotics/albatross-robot-sail-seed-boat/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/5465d03/2147483647/strip/true/crop/1964x1310+0+0/resize/1439x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2Fb6%2F45%2F9c4e5b844ef9b5c509ca50904ffa%2Falbatross-prototype-in-mid-flight-during-its-autorotating-descent.jpeg","d":"2026-10-17T16:03-03:00","c":["microrrobos"],"l":1,"to":"Bioinspired robot airdrops into remote waters via morphing wing-sail","lg":"en","esp":1,"p":11.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Na realidade, descreve uma nova plataforma robótica que os cientistas criaram para uma implantação rápida e a longo prazo para monitorizar águas remotas. Pesquisadores da Universidade de Tecnologia e Design de Cingapura (SUTD) desenvolveram o que chamam de ALBATROS, abreviação de Airborne Lander with Buoyant AuToROtating Sailing Sensor; uma plataforma robótica conceitual inspirada na natureza que pode ser implantada a partir de uma aeronave sobre águas remotas, pousar na água, endireitar-se e navegar de forma autônoma usando energia eólica.\n“Com o ALBATROS, queríamos usar o melhor dos dois mundos: a velocidade da implantação aérea para alcançar rapidamente águas remotas e a resistência da navegação para permanecer lá para monitoramento de longa duração.” Num cenário prático, uma aeronave transporta a plataforma ALBATROS através de águas abertas e a posiciona sobre uma área designada.","cur":1},{"id":"ccc78e744f5c1e","t":"Afastem-se, óculos pervertidos – a última tendência tóxica é o robogroping","r":"Sempre que uma nova tecnologia é criada, ela será, sem exceção, imediatamente usada para assediar meninas e mulheres. Você deve estar familiarizado com a regra 34 da Internet, que afirma que se algo existe ou pode ser imaginado, quase certamente haverá pornografia online. Agora deixe-me apresentar minha regra 35: sempre que um novo…","u":"https://www.theguardian.com/commentisfree/2026/oct/17/smartglasses-robogroping-toxic-trends","f":"The Guardian","s":"theguardian.com","i":"https://i.guim.co.uk/img/media/9fa4b3f31a0b0d7f2a9426914d86719d1efd2e0c/357_0_3570_2856/master/3570.jpg?width=140&quality=85&auto=format&fit=max&s=dcc45334faf456ad108647c4eae3ed16","d":"2026-10-17T10:00-03:00","c":["geral"],"l":0,"to":"Move over, pervert glasses – the latest toxic trend is robogroping","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"The Guardian","mx":1,"rx":"Sempre que uma nova tecnologia for criada, ela será, sem exceção, imediatamente usada para assediar meninas e mulheres. Agora deixe-me apresentar a minha regra 35: sempre que uma nova tecnologia for criada, ela será, sem exceção, imediatamente usada para assediar meninas e mulheres. Como qualquer um poderia ter previsto, colocar uma pequena câmera e um microfone em óculos inteligentes levaria imediatamente as pessoas a usá-los para gravar e assediar mulheres. Na verdade, na palestra do Meta Connect 2026, Mark Zuckerberg não sentiu necessidade de pedir desculpas às mulheres cujas vidas foram afetadas pela sua tecnologia.\nE, claro, existem os geradores de imagens de IA, que têm sido usados ​​para criar pornografia falsa de mulheres e meninas. De acordo com um relatório de 2023, “a pornografia deepfake representou 98% de todos os vídeos deepfake online e 99% retratava mulheres”."}],"2026-10-16":[{"id":"b8f4f36ff32f03","t":"Vídeo sexta-feira: quando dois robôs se tornam um","r":"Video Friday é sua seleção semanal de vídeos incríveis de robótica, coletados por seus amigos do IEEE Spectrum Robotics. Também publicamos um calendário semanal dos próximos eventos de robótica para os próximos meses. Por favor, envie-nos seus eventos para inclusão. CoRL 2026: 9–12 de novembro de 2026, AUSTIN Humanoids 2026: 6–9 de dezembro de 2026…","u":"https://spectrum.ieee.org/video-friday-reconfigurable-robots","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/two-small-robots-with-long-limbs-and-bodies-linked-by-a-wire-join-connect-to-form-one-four-wheeled-robot-on-a-paved-pathway.gif?id=68443843&width=980","d":"2026-10-16T13:30-03:00","c":["competicoes","humanoides"],"l":0,"to":"Video Friday: When Two Robots Become One","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Sua seleção semanal de vídeos incríveis de robôs"},{"id":"b75d62d644deac","t":"Robot Talk Episódio 166 – Evolução de corpos e cérebros de robôs, com Rika Antonova","r":"Claire conversou com Rika Antonova, da Universidade de Cambridge, sobre o uso de inteligência artificial para desenvolver hardware e algoritmos robóticos complementares. Rika Antonova é professora associada da Universidade de Cambridge. Seus interesses de pesquisa incluem co-design, descoberta automatizada de algoritmos, eficiência de dados…","u":"https://robohub.org/robot-talk-episode-166-evolving-robot-bodies-and-brains-with-rika-antonova/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Rika-Antonova-425x354.jpg","d":"2026-10-16T08:36-03:00","c":["ia"],"l":0,"to":"Robot Talk Episode 166 – Evolving robot bodies and brains, with Rika Antonova","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Claire conversou com Rika Antonova, da Universidade de Cambridge, sobre o uso de inteligência artificial para desenvolver hardware e algoritmos robóticos complementares. Rika Antonova é professora associada da Universidade de Cambridge. Seus interesses de pesquisa incluem co-design, descoberta automatizada de algoritmos, aprendizagem por reforço com eficiência de dados, exploração, aprendizagem ativa e robótica. Depois de concluir um mestrado de pesquisa no Instituto de Robótica da Universidade Carnegie Mellon e um doutorado no KTH Royal Institute of Technology, Rika recebeu uma bolsa de inovação em computação na Universidade de Stanford. Antes disso, ela era engenheira de software sênior no Google."},{"id":"0a59a8c9363b8e","t":"Robô com hélice ferida salta e salta sobre obstáculos","r":"Lembra-se daquele jogo de “lápis dançantes” que os alunos brincavam, em que passavam dois lápis por um pequeno elástico, torciam-nos repetidamente e depois os soltavam para fazer os lápis pularem enquanto o elástico se desenrolava? Acontece que eles estavam envolvidos em uma robótica futurista séria, já que os cientistas agora estão aplicando aproximadamente…","u":"https://newatlas.com/robotics/tiny-snapping-robot/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/aa5f254/2147483647/strip/true/crop/1314x876+0+0/resize/1314x876!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2Fc2%2F84%2F01aa861b443498ebf4b958e9cdda%2Fhopping-robot-1.jpeg","d":"2026-10-16T20:03-03:00","c":["educacao"],"l":0,"to":"Wound-helix robot leaps and bounds over obstacles","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Lembra-se daquele jogo de “lápis dançantes” que os alunos brincavam, em que passavam dois lápis por um pequeno elástico, torciam-nos repetidamente e depois os soltavam para fazer os lápis pularem enquanto o elástico se desenrolava? Pesquisadores da Escola de Engenharia Samueli da UCLA e da Universidade de Michigan construíram um robô parecido com um sapo que se move usando hastes flexíveis que se alternam repetidamente entre as formas. Pequenos motores carregam as hastes com energia, que elas liberam em rajadas repentinas para impulsionar a máquina. O robô pode pular na grama e na areia, subir pequenos degraus e, com nadadeiras presas, até nadar.\nAgora, os engenheiros já usam molas para contornar este problema: um motor carrega gradualmente a mola, armazenando a energia cinética do motor como energia potencial que pode então ser libertada rapidamente para lançar o robô."},{"id":"84c2c565c396ae","t":"Um insider da Nvidia que virou VC sobre por que a robótica ainda não atingiu seu momento ChatGPT","r":"Amulya Vishwanath, que passou sete anos liderando o marketing de produtos para as plataformas robóticas da NVIDIA, diz que a robótica está atualmente em sua “era Lego”, com os blocos de construção básicos como atuadores, mãos robóticas, software e padrões de segurança ainda sendo reconstruídos. Esta visão vai contra aqueles que acreditam que a robótica…","u":"https://techcrunch.com/video/a-nvidia-insider-turned-vc-on-why-robotics-hasnt-hit-its-chatgpt-moment-yet/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/06/unitree-robots.jpg?resize=1200,800","d":"2026-10-16T13:30-03:00","c":["educacao"],"l":0,"to":"An Nvidia insider-turned-VC on why robotics hasn’t hit its ChatGPT moment, yet","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"Amulya Vishwanath, que passou sete anos liderando o marketing de produtos para as plataformas robóticas da NVIDIA, diz que a robótica está atualmente em sua “era Lego”, com os blocos de construção básicos como atuadores, mãos robóticas, software e padrões de segurança ainda sendo reconstruídos. Esta visão vai contra aqueles que acreditam que a robótica, alimentada por um modelo de base geral, está prestes a ter o seu “momento ChatGPT” – aquele dia em que o chatbot surpreendentemente capaz foi lançado no final de 2022. (O CEO da General Intuition, Pim de Witte, disse à Equity no início deste ano que um único modelo de base geral tornaria redundante grande parte do trabalho robótico especializado de hoje, e seria esse momento.)\nNeste episódio do podcast Equity do TechCrunch, Dominic-Madori Davis conversou com Vishwanath para discutir onde ela está assinando os primeiros cheques como fundadora e sócia-gerente da Techable VC."},{"id":"1db14d807722c8","t":"A IA física é mais do que robôs, diz o veterano da Nvidia que agora investe nela","r":"Amulya Vishwanath, que passou sete anos liderando o marketing de produtos para as plataformas robóticas da NVIDIA, diz que a robótica está atualmente em sua “era Lego”, com os blocos de construção básicos como atuadores, mãos robóticas, software e padrões de segurança ainda sendo reconstruídos. Esta visão vai contra aqueles que acreditam que a robótica…","u":"https://techcrunch.com/podcast/physical-ai-is-more-than-robots-says-the-nvidia-veteran-now-investing-in-it/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/10/Amulya-Vishwanath-Techable-VC.jpg?resize=960,1200","d":"2026-10-16T13:30-03:00","c":["ia","educacao"],"l":0,"to":"Physical AI is more than robots, says the Nvidia veteran now investing in it","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"Amulya Vishwanath, que passou sete anos liderando o marketing de produtos para as plataformas robóticas da NVIDIA, diz que a robótica está atualmente em sua “era Lego”, com os blocos de construção básicos como atuadores, mãos robóticas, software e padrões de segurança ainda sendo reconstruídos. Esta visão vai contra aqueles que acreditam que a robótica, alimentada por um modelo de base geral, está prestes a ter o seu “momento ChatGPT” – aquele dia em que o chatbot surpreendentemente capaz foi lançado no final de 2022. (O CEO da General Intuition, Pim de Witte, disse à Equity no início deste ano que um único modelo de base geral tornaria redundante grande parte do trabalho robótico especializado de hoje, e seria esse momento.)\nNeste episódio do podcast Equity do TechCrunch, Dominic-Madori Davis conversou com Vishwanath para discutir onde ela está assinando os primeiros cheques como fundadora e sócia-gerente da Techable VC."}],"2026-10-15":[{"id":"acc8c088f14763","t":"Crítica de Klara e o Sol – A ficção científica maníaca do robô dos sonhos de duende de Taika Waititi é uma bagunça sentimental","r":"O diretor de Hunt for the Wilderpeople e Jojo Rabbit transforma a fábula de IA de Kazuo Ishiguro em um conto cansativo e cansativo de amor e tristeza. Taika Waititi detona uma explosão de estranheza pós-moderna e idiotice irônica neste filme insuportavelmente educado e indescritivelmente atuado. É uma fatia de futurismo sentimental e caprichoso e…","u":"https://www.theguardian.com/film/2026/oct/15/klara-and-the-sun-review-taika-waititi-kazuo-ishiguro","f":"The Guardian","s":"theguardian.com","i":"https://i.guim.co.uk/img/media/f55061596ee9bbd917a6bb5a6f872bb89a19c8e4/532_0_2637_2110/master/2637.jpg?width=140&quality=85&auto=format&fit=max&s=1b809d5a2c9860c1dd0a972a2adbfc56","d":"2026-10-15T17:15-03:00","c":["geral"],"l":0,"to":"Klara and the Sun review – Taika Waititi’s manic pixie dream robot sci-fi is a sentimental mess","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"The Guardian","mx":1,"rx":"O diretor de Hunt for the Wilderpeople e Jojo Rabbit transforma a fábula de IA de Kazuo Ishiguro em um conto cansativo e cansativo de amor e tristeza. É uma fatia de capricho sentimental, futurismo e não sátira, adaptado por Waititi do romance de Kazuo Ishiguro, que acaba não dizendo nada substancial ou significativo (ou engraçado) sobre inteligência artificial, amor ou tristeza. Klara and the Sun é uma ficção científica centrada na suavidade, exigindo simultaneamente que riamos de seu humor (sem graça) e enxugamos uma lágrima por sua pungência.\nUma dessas AF é a adolescente Klara, interpretada por Jenna Ortega como uma inocente estúpida, fofa e extremamente adorável: um robô dos sonhos duende maníaco - só que legal - que é movido a energia solar e que, portanto, em seu adorável jeito infantil de robô, adora o sol como um deus."}],"2026-10-14":[{"id":"05f923284a96fd","t":"Planejamento neurosimbólico utilizando comunicação em linguagem natural para veículos autônomos cooperativos","r":"Imagine que você está dirigindo em direção a um cruzamento. Um caminhão estacionado na esquina bloqueia a visão de um carro em alta velocidade em direção ao cruzamento pela direita. Você não pode ver, mas o carro ao seu lado pode. E se o veículo vizinho pudesse simplesmente dizer ao seu carro: “Veículo se fundindo pela direita, a cerca de 15 metros de distância…","u":"https://robohub.org/neurosymbolic-planning-using-natural-language-communication-for-cooperative-autonomous-vehicles/","f":"Robohub","s":"robohub.org","i":"https://aihub.org/wp-content/uploads/2026/09/birds-eye.jpeg","d":"2026-10-14T06:14-03:00","c":["autonomos"],"l":0,"to":"Neurosymbolic planning using natural language communication for cooperative autonomous vehicles","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Esta ideia simples de que os carros se ajudam mutuamente, descrevendo o que vêem em linguagem natural, motiva o UNCAP, o nosso novo quadro para a condução autónoma cooperativa. A UNCAP ensina aos veículos autónomos com quem devem falar e até que ponto devem confiar no que ouvem. Essas mensagens descrevem veículos próximos, movimento e confiança, que o UNCAP combina antes de tomar uma decisão de direção.\nAvaliamos o UNCAP no popular simulador de direção CARLA usando o benchmark OPV2V, que é um benchmark amplamente utilizado por pesquisadores de direção autônoma. UNCAP: Planejamento neurosimbólico guiado pela incerteza usando comunicação de linguagem natural para veículos autônomos cooperativos, Neel P. Bhatt, Po-han Li, Kushagra Gupta, Rohan Siva, Daniel Milan, Alexander T. Hogue, Sandeep P. Chinchali, David Fridovich-Keil, Zhangyang Wang, Ufuk Topcu."},{"id":"2e447a71d8fc2e","t":"Economize 50% no seu ingresso TechCrunch Disrupt 2026 e participe dos últimos 2 dias no Moscone West de São Francisco","r":"Ganhe 50% de desconto nos últimos dois dias do TechCrunch Disrupt 2026, de 14 a 15 de outubro, em São Francisco. Cadastre-se agora e junte-se ao restante do ecossistema de startups. Hoje, tudo se resume à IA física e de software.","u":"https://techcrunch.com/2026/10/14/save-50-on-your-techcrunch-disrupt-2026-ticket-and-join-the-last-two-days-in-san-francisco/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/10/55588061334_e461da18f4_k.jpg?resize=1200,800","d":"2026-10-14T12:13-03:00","c":["ia","negocios"],"l":0,"to":"Save 50% on your TechCrunch Disrupt 2026 ticket and join the last 2 days in San Francisco’s Moscone West","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"O primeiro dia do TechCrunch Disrupt 2026 pode ter terminado, mas ainda há muito mais programação do Disrupt no Moscone West de São Francisco nos dias 14 e 15 de outubro. Faltando apenas dois dias para o fim do evento, estamos oferecendo um desconto correspondente: ganhe dois dias inteiros de Disrupt com 50% de desconto em todos os tipos de ingressos, o que torna muito mais fácil assistir a alguns de nossos palestrantes e programação mais cativantes.\nPor exemplo, no Disrupt Stage, ainda temos palestrantes estelares como o ator de primeira linha Mark Wahlberg, o CEO da Replit Amjad Masad, todos os cinco parceiros da Benchmark em uma rara aparição conjunta, Panos Panay da Amazon, o CEO e COO da Bluesky Toni Schneider e Rose Wang… a lista continua. Além disso, a competição de campo do Startup Battlefield 200 ainda está forte no Disrupt Stage."}],"2026-10-13":[{"id":"8c227999949ccc","t":"Perguntas e respostas: Mars Perseverance Rover estabelece um recorde de distância","r":"Em 11 de outubro, o rover Perseverance completou uma viagem que elevou a distância total percorrida em Marte para 28,10 milhas (45,22 quilômetros). Este é um novo recorde para os rovers de Marte, possibilitado em grande parte pela capacidade do Perseverance de conduzir com muito mais autonomia do que os seus antecessores. Nos últimos cinco anos…","u":"https://spectrum.ieee.org/mars-rover-distance-record","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/a-long-trail-of-tire-tracks-left-across-mars-dusty-surface-by-a-space-rover.jpg?id=68423735&width=980","d":"2026-10-13T12:02-03:00","c":["espaco"],"l":0,"to":"Q&A: Mars Perseverance Rover Sets a Distance Record","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Uma das câmeras de navegação do Perseverance capturou esta foto em 11 de outubro de 2026, o dia em que uma viagem de 299,6 pés ultrapassou o recorde de 28,06 milhas do Opportunity em Marte.","cur":1},{"id":"106143bfb96d49","t":"A IA pode agir exatamente como um ser humano, mas ainda não achamos que seja consciente","r":"Um novo estudo revela que as pessoas traçam uma linha surpreendentemente nítida entre a consciência humana e a inteligência artificial, mesmo quando ambas se comportam de forma idêntica. Os pesquisadores descobriram que os participantes consideravam até mesmo a IA mais responsiva menos consciente do que o ser humano menos responsivo. No entanto, quando questionado sobre “consciência”…","u":"https://www.sciencedaily.com/releases/2026/10/261012185017.htm","f":"Robotics Research News -- ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/human-vs-ai-brain-thinking-understanding.webp","d":"2026-10-13T22:41-03:00","c":["ia"],"l":0,"to":"AI can act exactly like a human, but we still don't think it's conscious","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"Mesmo quando a inteligência artificial se comporta exatamente como um ser humano, as pessoas relutam em considerá-la consciente, de acordo com um novo estudo da Universidade Ludwig Maximilian de Munique (LMU). Mas será que comportar-se como um humano realmente convence as pessoas de que uma máquina tem consciência? Uma nova pesquisa da LMU sugere que as pessoas fazem uma distinção clara entre exibir um comportamento inteligente e possuir uma mente consciente, mesmo quando os humanos e a IA agem precisamente da mesma maneira.\nAs pessoas atribuem consistentemente menos consciência à IA do que os humanos - mesmo quando o seu comportamento é idêntico.\" Os investigadores acreditam que a diferença entre consciência e consciência oferece uma visão importante sobre como as pessoas entendem a inteligência artificial.","cur":1},{"id":"3bfcfa2b67d196","t":"A startup Mind Robotics de Rivian contrata o ex-chefe de EV da Ford, Doug Field","r":"Field também trabalhou no projeto secreto do carro da Apple e supervisionou o desenvolvimento do Tesla Model 3.","u":"https://techcrunch.com/2026/10/13/rivians-startup-mind-robotics-hires-former-ford-ev-chief-doug-field/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/04/Doug-Field.jpg?resize=800,1200","d":"2026-10-13T15:30-03:00","c":["negocios"],"l":0,"to":"Rivian’s startup Mind Robotics hires former Ford EV chief Doug Field","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"Agora o executivo está voltando sua atenção para o mais recente projeto do CEO da Rivian, RJ Scaringe: Mind Robotics. Field foi contratado como presidente da Mind Robotics, um empreendimento industrial de IA e robótica criado no ano passado por Scaringe e apoiado por Rivian. Scaringe ainda estará envolvido com a Mind Robotics, mas os aspectos do dia a dia do negócio, incluindo produto, engenharia e operações, serão tratados por Field.\nA participação de Rivian na Mind Robotics foi diluída desde que recebeu apoio adicional; Rivian detém 32,1% de participação na Mind Robotics em junho de 2026, de acordo com registros regulatórios. Assim como acontece com Field e Mind Robotics, Scaringe está envolvido como presidente da Also, mas contratou alguém para administrar o dia-a-dia: Chris Yu, ex-diretor de produto da Specialized."},{"id":"f267b0c17dba1c","t":"A Industrial Next quer que os robôs de fábrica troquem de tarefa em minutos, não em semanas","r":"A Industrial Next ajuda os fabricantes a automatizar tarefas complexas e delicadas que tradicionalmente exigiam mão de obra humana.","u":"https://techcrunch.com/2026/10/13/industrial-next-wants-factory-robots-to-switch-tasks-in-minutes-not-weeks/","f":"Robotics News | TechCrunch","s":"techcrunch.com","i":"https://techcrunch.com/wp-content/uploads/2026/10/GettyImages-2247792889.jpg?resize=1200,788","d":"2026-10-13T20:00-03:00","c":["industriais"],"l":0,"to":"Industrial Next wants factory robots to switch tasks in minutes, not weeks","lg":"en","esp":1,"p":4.3,"cr":2,"cv":"TechCrunch","mx":1,"rx":"O objetivo é permitir que os fabricantes automatizem tarefas complexas e delicadas que tradicionalmente exigem trabalho humano. A Industrial Next foi fundada em 2021 por Lukas Pankau e Allen Pan, que já trabalharam na Tesla. Pankau observa que os robôs industriais tradicionais são normalmente programados para executar tarefas altamente específicas e repetíveis. Eles realizam tarefas que os fabricantes tentaram e não conseguiram automatizar durante anos, como passar um cabo flexível delicado e encaixar uma pequena tampa de conector no lugar. (Ele não tinha liberdade de divulgar o cliente.) Ele também descreveu uma estação de “remoção de filme”, onde seus robôs alimentados por IA retiram a película protetora dos módulos e botões da câmera na velocidade humana ou acima dela com 100% de precisão, mesmo quando movidos para um novo modelo de telefone e linha de produção que eles nunca viram."}],"2026-10-12":[{"id":"46d23cf3c528c9","t":"Robôs humanóides podem correr e lutar boxe – mas o verdadeiro teste é lavar a roupa","r":"Por Wai-keung Fung, Universidade Metropolitana de Cardiff Nos recentes Jogos Mundiais de Robôs Humanóides de 2026, em Pequim, robôs correram, lutaram boxe, jogaram futebol e realizaram tarefas inspiradas em fábricas, restaurantes e situações de emergência. O robô Tiangong Ultra chegou a completar os 100 metros em 8,64 segundos, mais rápido que Usain…","u":"https://robohub.org/humanoid-robots-can-sprint-and-box-but-the-real-test-is-doing-the-laundry/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/sophiamartin-clothes-pins-8281931-1024x683.jpg","d":"2026-10-12T04:51-03:00","c":["humanoides","competicoes","casa","industriais"],"l":0,"to":"Humanoid robots can sprint and box – but the real test is doing the laundry","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"Robohub","mx":1,"rx":"Nos recentes Jogos Mundiais de Robôs Humanóides de 2026, em Pequim, os robôs correram, lutaram boxe, jogaram futebol e realizaram tarefas inspiradas em fábricas, restaurantes e situações de emergência. Mas se quisermos realmente saber se os robôs humanóides estão prontos para a vida quotidiana, um desafio muito menos glamoroso poderá dizer-nos mais: lavar a roupa. Será que um robô consegue tirar uma camiseta amassada de um cesto de roupa suja, descobrir em que direção ela fica, dobrá-la com cuidado e recuperá-la quando a manga escorregar de sua mão?\nNenhum sistema robótico consegue ainda lidar de forma confiável com todo o processo de lavanderia, desde carregar um cesto até a máquina de lavar e separar as roupas para diferentes programas, até retirá-las, pendurá-las para secar, dobrá-las e passá-las. A lavanderia é um problema muito diferente."},{"id":"8d2dd139afe497","t":"O bot bípede usa seu telefone antigo e empoeirado como cérebro","r":"Aquele velho telefone acumulando poeira em uma gaveta poderia ter uma segunda vida muito mais divertida do que ser um peso de papel. Pesquisadores da UCLA criaram o PhoneBot, um pequeno humanóide que coloca seu smartphone para funcionar como o cérebro de um robô ambulante. Continue lendo Categoria: Robótica, Engenharia Tags: UCLA…","u":"https://newatlas.com/robotics/ucla-scientists-android-phone-walking-robot-companion/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/c8906ec/2147483647/strip/true/crop/1376x768+0+0/resize/1376x768!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F0e%2F71%2Fb25311df449aa951e065e299e779%2Fgenerated-image-5.png","d":"2026-10-12T22:10-03:00","c":["humanoides"],"l":0,"to":"Biped bot uses your old, dusty phone for brains","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"New Atlas","mx":1,"rx":"Aquele velho telefone acumulando poeira em uma gaveta poderia ter uma segunda vida muito mais divertida do que ser um peso de papel. Pesquisadores da UCLA criaram o PhoneBot, um pequeno humanóide que coloca seu smartphone para funcionar como o cérebro de um robô ambulante. Em uma pré-impressão publicada no arXiv, a equipe descreve um robô bípede que usa um smartphone como torso, olhos e cérebro.\nNo robô real, a equipe demonstrou caminhar, seguir uma pessoa com a câmera e levantar-se deitada de bruços. Caminhada e visão funcionam no próprio telefone. Os pesquisadores testaram o PhoneBot em quatro telefones Android: um Honor 9 de 2017 e três modelos pré-pagos comprados por cerca de US$ 50 a US$ 80. Ainda assim, o artigo não estabelece que o PhoneBot funcionará com todos os telefones Android."}],"2026-10-11":[{"id":"737baac53b7ea9","t":"O motor suíço incrivelmente minúsculo parece tudo menos","r":"Se você já projetou um robô de corpo mole, isso vai contra o propósito se você simplesmente colocar um motor rígido dentro dele. É por isso que os cientistas suíços criaram um motor que tem a forma de uma fibra fina e flexível. Continue lendo Categoria: Robótica, Engenharia Tags: EPFL, Soft Robotics, Artificial…","u":"https://newatlas.com/robotics/fibermotor-flexible-motor/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/4201e9f/2147483647/strip/true/crop/6240x3504+0+0/resize/1440x809!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F0b%2F02%2F2f2113c748babb9da612e48faf92%2F6240x3504-2.jpg","d":"2026-10-11T08:00-03:00","c":["microrrobos"],"l":0,"to":"Impossibly tiny Swiss motor looks like anything but","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Se você já projetou um robô de corpo mole, isso vai contra o propósito se você simplesmente colocar um motor rígido dentro dele. É por isso que os cientistas suíços criaram um motor que tem a forma de uma fibra fina e flexível. Variando em diâmetro de 1 a 3 milímetros, cada FiberMotor é na verdade composto por duas fibras de polímero ocas concêntricas – uma mais larga na parte externa, com uma mais estreita aninhada dentro dela. Um fio de cobre fino é enrolado firmemente em torno de cada uma das fibras, servindo como eletrodo em cada fibra.\n“Nosso FiberMotor é o primeiro motor deslizante em formato de fibra”, diz Herbert Shea, chefe do Laboratório de Transdutores Suaves da EPFL. “Ele produz força suficiente para acionar dispositivos para aplicações robóticas suaves, permanecendo silencioso, flexível e bidirecional.”"},{"id":"ccf8f2c90df556","t":"Robô bombeador de água percorre terreno costeiro acidentado","r":"A biomimética envolve emprestar ideias da natureza para resolver problemas de engenharia. É nisso que uma das equipes de pesquisa da Escola de Engenharia Tandon da Universidade de Nova York se especializa. Recentemente, cobrimos seu robô inspirado em peixes, então a exploração de corpos d'água parece estar resolvida. Continue lendo Categoria…","u":"https://newatlas.com/robotics/worma-weight-shifting-worm-robot/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/d1b94a5/2147483647/strip/true/crop/2500x1666+0+0/resize/1440x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2Ffb%2F59%2Fecdc58c94dc3aa1f5ad14a363268%2Fscreenshot-2026-10-07-at-11-10-53-am.jpeg","d":"2026-10-11T21:35-03:00","c":["educacao"],"l":0,"to":"Water-pumping robot worms its way over rugged coastal terrain","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Recentemente, cobrimos seu robô inspirado em peixes, então explorar corpos d'água parece estar resolvido. Uma bomba na seção intermediária move esses 300 gramas (10,6 onças) de água entre a cabeça e a cauda, ​​mudando o centro de massa do robô dependendo de onde ele precisa ir. Quando o WorMa precisa escalar uma superfície inclinada, a água se desloca em direção à sua cabeceira. A massa de água move-se para a cauda, ​​deslocando o peso do robô para trás e ajudando-o a nadar cerca de 26% mais rápido do que poderia de outra forma. E quando precisa sair da água e voltar para a costa, a água se move novamente em direção à cabeça, dando à frente do robô tração suficiente para puxar-se para uma superfície inclinada.\nUma vez que a cabeça e a articulação do “pescoço” estejam ancoradas na borda do degrau, a água se desloca novamente para a cabeça, para que o robô possa puxar a cauda para frente e o ciclo se repete."}],"2026-10-10":[{"id":"576371a7352268","t":"O robô saltador de última geração é a pulga inteligente que não sabíamos que precisávamos","r":"Já vimos robôs que podem nadar como peixes, aderir às paredes como lagartixas e agarrar objetos como elefantes. Agora, engenheiros da Universidade de Washington estão construindo um novo tipo de robô inspirado… na pulga. Continue lendo Categoria: Robótica, Engenharia Tags: Universidade de Washington, locomoção…","u":"https://newatlas.com/robotics/flea-inspired-directhop-hopping-robot/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/d09ad29/2147483647/strip/true/crop/8192x5464+0+0/resize/1439x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F75%2Fd8%2F5260890643bfae93aa0bdc8452a6%2Fdirecthop1.jpg","d":"2026-10-10T12:00-03:00","c":["ia"],"l":1,"to":"Next-gen hopping robot is the smart flea we didn't know we needed","lg":"en","esp":1,"p":11.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Já vimos robôs que podem nadar como peixes, aderir às paredes como lagartixas e agarrar objetos como elefantes. Agora, engenheiros da Universidade de Washington estão construindo um novo tipo de robô inspirado… na pulga. Os pesquisadores chamaram seu novo projeto de DirectHop, o que revela a ideia principal: é um robô saltitante. A maioria dos robôs saltadores existentes usa um mecanismo de carregamento por mola, que tem um problema de “tudo ou nada”: eles são projetados para liberar uma quantidade fixa de energia, tornando muito difícil ajustar a altura e a distância de cada salto.\nDirectHop é capaz de pular mais alto do que uma escada padrão, o que é bastante impressionante para um robô do seu tamanho. A parte interessante é que o robô não salta empurrando com as pernas como fazem os insetos ou sapos."}],"2026-10-09":[{"id":"955fb13e8a09c6","t":"O ‘cachorro-robô’ sul-coreano se tornou o primeiro a correr uma maratona com uma única carga de bateria – agora sabemos como","r":"Um robô de quatro patas completou uma maratona completa com uma única carga de bateria, percorrendo 42,2 quilômetros em um percurso montanhoso em uma estrada pública na Coreia do Sul, há dois anos. Agora sabemos muito mais sobre como conseguiu esse feito recorde. O robô parecido com um cachorro, chamado RAIBO2, terminou o 22º Sangju anual…","u":"https://www.livescience.com/technology/robotics/south-korean-robot-dog-becomes-first-to-run-a-marathon-on-a-single-battery-charge","f":"Live Science","s":"livescience.com","i":"https://cdn.mos.cms.futurecdn.net/fq4PmYy3DKyBcWarUdvndJ-1920-80.jpg","d":"2026-10-09T06:00-03:00","c":["quadrupedes","competicoes"],"l":0,"to":"South Korean 'robot dog' became first to run a marathon on a single battery charge — now we know how","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"Live Science","mx":1,"rx":"Um robô de quatro patas completou uma maratona completa com uma única carga de bateria, percorrendo 42,2 quilômetros em um percurso montanhoso em uma estrada pública na Coreia do Sul, há dois anos. O robô parecido com um cachorro, chamado RAIBO2, terminou a 22ª Maratona Anual de Caqui Seco de Sangju em pouco mais de 4 horas e 19 minutos. Os desenvolvedores do bot dizem que é o primeiro robô quadrúpede a completar uma prova oficial de maratona sem parar para recarregar.\nO RAIBO2 já havia percorrido uma rota guiada por GPS de 26,7 milhas (43 km) através de um campo de atletismo plano, que derrubou em 4 horas e 40 minutos com uma carga. No entanto, uma tentativa anterior de maratona em terreno irregular contra outros competidores teve que ser abortada perto da marca de 37 km depois que a bateria do robô acabou."},{"id":"96aa397c58482d","t":"Vídeo sexta-feira: o descomissionamento do robô dá uma reviravolta divertida","r":"Video Friday é sua seleção semanal de vídeos incríveis de robótica, coletados por seus amigos do IEEE Spectrum Robotics. Também publicamos um calendário semanal dos próximos eventos de robótica para os próximos meses. Por favor, envie-nos seus eventos para inclusão. CoRL 2026: 9–12 de novembro de 2026, AUSTIN Humanoids 2026: 6–9 de dezembro de 2026…","u":"https://spectrum.ieee.org/video-friday-reachy-mini-raps","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/an-ai-generated-image-of-a-smiling-humanoid-robot-in-robe-free-falls-into-deep-pit-filled-with-colorful-balls.jpg?id=68398684&width=980","d":"2026-10-09T12:30-03:00","c":["competicoes","humanoides"],"l":0,"to":"Video Friday: Robot Decommissioning Takes a Fun Turn","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Mesmo que seja IA, uma piscina de bolinhas torna o descomissionamento divertido para o robô – ou apenas para quem está assistindo?"},{"id":"a3814cfc4afef9","t":"Robot Talk Episódio 165 – Robôs por trás da pesquisa, com Kushant Patel","r":"Claire conversou com Kushant Patel, do Laboratório Nacional de Brookhaven, sobre robôs que trabalham em instalações científicas, como aceleradores de partículas. Kushant Patel desenvolve software que ajuda robôs e instrumentos a perceber, mapear e se mover pelo mundo físico. Depois de concluir o Mestrado em Engenharia Mecatrónica…","u":"https://robohub.org/robot-talk-episode-165-robots-behind-the-research-with-kushant-patel/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Kushant-Patel-319x425.jpg","d":"2026-10-09T08:52-03:00","c":["ia"],"l":0,"to":"Robot Talk Episode 165 – Robots behind the research, with Kushant Patel","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Claire conversou com Kushant Patel, do Laboratório Nacional de Brookhaven, sobre robôs que trabalham em instalações científicas, como aceleradores de partículas. Kushant Patel desenvolve software que ajuda robôs e instrumentos a perceber, mapear e se mover pelo mundo físico. Depois de concluir um mestrado em Engenharia Mecatrônica na Universidade de Waterloo, ele passou dois anos na Universidade da Califórnia, Berkeley, ensinando robôs quadrúpedes para mapear e inspecionar materiais nucleares, e um ano na Universidade da Califórnia, Davis, construindo interfaces cérebro-computador de circuito fechado. No Laboratório Nacional de Brookhaven, ele está desenvolvendo sistemas de controle para linhas de luz síncrotron avançadas."},{"id":"8e3487fd93ea8b","t":"O vídeo de boxe entre o influenciador Frankie LaPenna e um robô: era tão real que houve ferimentos","r":"","u":"https://news.google.?oc=5","f":"Infobae","s":"infobae.com","i":"","d":"2026-10-09T04:00-03:00","c":["competicoes"],"l":0,"to":"El video de boxeo entre el influencer Frankie LaPenna y un robot: fue tan real que hubo lesiones","lg":"es","p":3.5,"cr":3,"cv":"Infobae","mx":0}],"2026-10-08":[{"id":"a2b57285998e01","t":"Esta mão desencarnada é todo o robô que você precisa","r":"Uma mão presa à ponta de um braço é um dado adquirido para a maioria dos humanos, mas e se os robôs não tivessem que seguir as mesmas regras que nós? Pesquisadores da ETH Zurich transformaram uma mão robótica pronta para uso em um robô completamente independente que anda na ponta dos dedos enquanto usa esses mesmos dedos para manipular seus…","u":"https://spectrum.ieee.org/walking-robotic-hand","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/a-detached-robotic-hand-using-its-five-fingers-to-walk.jpg?id=68383398&width=980","d":"2026-10-08T09:00-03:00","c":["ia"],"l":0,"to":"This Disembodied Hand Is All the Robot You Need","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Com um pouco de modificação e treinamento, uma mão robótica pronta para uso pode ser um robô móvel completo."}],"2026-10-07":[{"id":"e36f82a2f284ee","t":"Roboticistas apresentam um pequeno robô parecido com um sapo que pode pular em superfícies molhadas e nadar","r":"O reino animal influenciou vários projetos de robôs ao longo dos anos para resolver desafios fundamentais de propulsão e movimento — de cavalos a insetos. Agora, os sapos são as últimas criaturas a inspirar os roboticistas. Conforme visto em um novo estudo publicado em 18 de setembro na revista Science Advances, os pesquisadores investigaram como…","u":"https://www.livescience.com/technology/robotics/roboticists-showcase-tiny-frog-like-robot-that-can-hop-across-wet-surfaces-and-swim","f":"Live Science","s":"livescience.com","i":"https://cdn.mos.cms.futurecdn.net/uE53MhooqxHaSvjTJUUW9R-1920-80.jpg","d":"2026-10-07T06:00-03:00","c":["ia"],"l":1,"to":"Roboticists showcase tiny, frog-like robot that can hop across wet surfaces and swim","lg":"en","esp":1,"p":11.6,"cr":3,"cv":"Live Science","mx":1,"rx":"Acesso ilimitado aos nossos recursos exclusivos, análises de especialistas e entrevistas detalhadas, tudo sem anúncios. Em 18 de agosto na revista Science Advances, os pesquisadores investigaram como a torção de hastes elásticas dobradas poderia produzir um \"movimento de estalo\" que permitia a um pequeno robô pular ou nadar. “A oportunidade mais ampla é permitir que a mecânica do robô faça parte do trabalho que, de outra forma, exigiria motores maiores ou um controle mais complicado”, disse Xiaonan (Sean) Huang, professor assistente de robótica na Universidade de Michigan e co-primeiro autor do estudo, disse em um comunicado.\n“No futuro, este princípio poderá ser útil para robôs que devem navegar em terrenos desordenados, superar obstáculos, reorientar-se rapidamente ou operar tanto em terra como na água.” Quando uma haste flexível se dobra e suas extremidades são giradas, ela pode eventualmente chegar a um ponto em que muda de forma para liberar a tensão acumulada, disseram os roboticistas."},{"id":"259ac77af9d3d5","t":"HiPHI: uma referência em larga escala para movimentos humanos de alta precisão e interação de objetos","r":"Este white paper oferece aos pesquisadores e engenheiros de robótica uma visão geral de um novo conjunto de dados de captura de movimento em grande escala construído para preencher a lacuna de dados que limita o aprendizado de robôs humanóides. Ele também mostra como as políticas treinadas no conjunto de dados são transferidas para um robô humanóide real. Sobre o que você aprenderá: Por que o aprendizado de robôs humanóides, um…","u":"https://content.knowledgehub.wiley.com/hiphi-a-large-scale-benchmark-for-high-precision-human-motion-and-object-interaction/","f":"IEEE Spectrum","s":"content.knowledgehub.wiley.com","i":"https://assets.rbl.ms/68382308/origin.png","d":"2026-10-07T10:49-03:00","c":["humanoides"],"l":0,"to":"HiPHI: A Large-Scale Benchmark for High-Precision Human Motion and Object Interaction","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Os sistemas de captura de movimento de laboratório registram movimentos precisos, mas geralmente cobrem apenas um conjunto restrito de ações. Este white paper examina o HiPHI, um conjunto de dados de movimento humano de corpo inteiro de 617,5 horas capturado com captura óptica de movimento com precisão submilimétrica. O artigo também apresenta um conjunto de benchmark para medir a diversidade de movimento e aterramento de interação, e relata resultados de políticas treinadas no conjunto de dados e implantadas em um robô humanóide físico Unitree G1.\nTópicos do mesmo nível 3 + mesmo patrocinador [1], 2. Tópicos do mesmo nível 2 + mesmo patrocinador [1], 3. Qualquer tópico + mesmo patrocinador [1], 2. Mesmas tags + mesmo patrocinador [1], 3."},{"id":"d82d439fcb604b","t":"O que três dias construindo um robô me ensinaram","r":"No mês passado, fui a York construir um robô. Voltei com um robô, uma pequena sensação de conquista em forma de troféu e, de alguma forma, alguns novos amigos. De 25 a 27 de agosto, participei do UK RAS STEPS MicroMaze Robot Hackathon no Institute for Safe Autonomy da Universidade de York. O briefing parecia simples: construir um pequeno…","u":"https://robohub.org/what-three-days-building-a-robot-taught-me/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/09/York_DevInYork-1024x576.jpeg","d":"2026-10-07T04:12-03:00","c":["ia"],"l":0,"to":"What three days building a robot taught me","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"No mês passado, fui a York construir um robô. Voltei com um robô, uma pequena sensação de conquista em forma de troféu e, de alguma forma, alguns novos amigos. De 25 a 27 de agosto, participei do UK RAS STEPS MicroMaze Robot Hackathon no Institute for Safe Autonomy da Universidade de York. A tarefa parecia simples: construir um pequeno robô autônomo e depois fazê-lo sobreviver a labirintos cada vez mais difíceis.\nAo longo de três dias, Emily, Joolz e eu passamos de uma caixa de peças e um chassi cortado a laser para um robô que poderia realmente percorrer um labirinto. Há algo bastante apropriado em pedir a uma sala cheia de técnicos que faça um pequeno robô autônomo se comportar sozinho. Um enorme obrigado a (sempre espirituoso e brincalhão) Rob Woolley por organizar o hackathon, e ao Institute for Safe Autonomy, Universidade de York e à equipe RAS STEPS do Reino Unido por criar essas oportunidades para Profissionais Técnicos de Pesquisa."},{"id":"607703e10baa49","t":"Pequeno robô coleta energia da bateria através da pele dos pés","r":"Os pesquisadores desenvolveram uma membrana fina como papel que permite que microrobôs rastejantes coletem eletricidade diretamente do solo abaixo deles, livrando-se de baterias pesadas a bordo, transformando superfícies de metal e silício em uma fonte de energia ativa. Continue lendo Categoria: Robótica, Engenharia Tags: Robótica, Pele…","u":"https://newatlas.com/robotics/robot-harvests-power-skin-feet-membrane/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/157fd10/2147483647/strip/true/crop/5120x3412+0+0/resize/1440x960!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2Fc8%2Fb8%2F05c7c7e54d82b5547a7d25ba0d6b%2Fdownload.jpeg","d":"2026-10-07T23:51-03:00","c":["agricolas","microrrobos"],"l":0,"to":"Tiny robot harvests battery power via skin on its feet","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Os pesquisadores desenvolveram uma membrana fina como papel que permite que microrobôs rastejantes coletem eletricidade diretamente do solo abaixo deles, livrando-se de baterias pesadas a bordo, transformando superfícies de metal e silício em uma fonte de energia ativa. Minúsculos microrrobôs poderiam escapar através dos escombros para localizar sobreviventes do terremoto ou inspecionar as fendas mais estreitas dos reatores nucleares, mas o seu maior obstáculo continua a ser notavelmente mundano: a energia.\nPesquisadores da Universidade Fudan, na China, contornaram totalmente o armazenamento a bordo, transformando o solo abaixo da máquina em uma fonte de alimentação. Em um estudo publicado na National Science Review, a equipe demonstrou uma membrana macia e fina como papel presa à almofada dos pés de um robô que gera eletricidade instantaneamente enquanto pisa em superfícies ativas como alumínio, zinco ou silício."}],"2026-10-06":[{"id":"5a217096e52d23","t":"Vídeo: Mão hábil de robô aprende a delicada arte do bordado em seda","r":"A Agilink, uma subsidiária da gigante chinesa de robótica AgiBot, pediu a Fu Xianghong, um mestre do bordado tradicional de Suzhou, que treinasse seu OmniHand 3 Ultra. A mão sintética aprendeu a dividir fios de seda, enfiar a linha na agulha, esticar o tecido na moldura e costurar, seguindo um ofício com mais de 2.500 anos de história…","u":"https://newatlas.com/robotics/agilink-robot-hand-learns-silk-embroidery/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/e4266ce/2147483647/strip/true/crop/3420x1700+0+0/resize/1440x716!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F38%2F38%2Ffe81e0694fed8cd4141a9d3c83fd%2Fscreenshot-2026-10-05-at-17-38-00.png","d":"2026-10-06T11:03-03:00","c":["humanoides"],"l":0,"to":"Video: Dexterous robot hand learns the delicate art of silk embroidery","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"New Atlas","mx":1,"rx":"A Agilink, uma subsidiária da gigante chinesa de robótica AgiBot, pediu a Fu Xianghong, um mestre do bordado tradicional de Suzhou, que treinasse seu OmniHand 3 Ultra. A mão sintética aprendeu a dividir fios de seda, enfiar a linha na agulha, esticar o tecido na moldura e costurar, seguindo um ofício com mais de 2.500 anos de história. Uma etapa fundamental no bordado Suzhou é dividir o fio de seda principal em fios individuais (16, de acordo com o vídeo abaixo).\nA Agilink não disse exatamente qual modelo aparece no vídeo, mas parece idêntico ao OmniHand 3 Ultra-M. Essa versão tem aproximadamente o tamanho de uma mão humana e pesa 630 g (1,4 lb). A Boston Dynamics seguiu outro caminho com a mão recém-revelada para seu robô Atlas, que possui apenas quatro dígitos."}],"2026-10-05":[{"id":"51ce0e457acc1b","t":"A pesquisa pode orientar o design futuro de robôs sociais","r":"Pela Universidade de Glasgow Dar aos companheiros robôs rostos e vozes semelhantes a animais ou estilo anime poderia maximizar seu apelo emocional para os usuários, de acordo com uma nova pesquisa que poderia ajudar a orientar o crescente campo da robótica social. Os robôs sociais podem proporcionar companheirismo e conforto aos seus proprietários, imitando humanos…","u":"https://robohub.org/research-could-guide-the-future-design-of-social-robots/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Screenshot-2026-09-27-at-10.29.52-1-425x249.png","d":"2026-10-05T07:00-03:00","c":["companhia"],"l":0,"to":"Research could guide the future design of social robots","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Dar aos companheiros robôs rostos e vozes semelhantes aos de animais ou de anime poderia maximizar seu apelo emocional aos usuários, de acordo com uma nova pesquisa que poderia ajudar a orientar o crescente campo da robótica social. “No entanto, o design estético dos robôs sociais zoomórficos até agora tem sido em grande parte o resultado de suposições fundamentadas, com muito pouca investigação disponível sobre o que os torna atractivos para os utilizadores.\nNesta pesquisa, a equipe começou criando um ‘mood board’ com imagens atraentes de animais e robôs retiradas da vida real e da cultura popular para ajudá-los a projetar uma série de protótipos de rostos para robôs virtuais. “Esperamos que nossas descobertas ajudem a informar o design das futuras gerações de tecnologia de robôs sociais zoomórficos, mas também possam estender a vida útil dos dispositivos existentes, permitindo que os usuários sobreponham novos rostos, vozes e funcionalidades usando realidade aumentada.”"}],"2026-10-02":[{"id":"00bb782fa200db","t":"Sexta-feira de vídeo: Albatross Falls, Spins, Self-Rights e Sails Away","r":"Video Friday é sua seleção semanal de vídeos incríveis de robótica, coletados por seus amigos do IEEE Spectrum Robotics. Também publicamos um calendário semanal dos próximos eventos de robótica para os próximos meses. Por favor, envie-nos seus eventos para inclusão. CoRL 2026: 9–12 de novembro de 2026, AUSTIN Humanoids 2026: 6–9 de dezembro de 2026…","u":"https://spectrum.ieee.org/video-friday-bioinspired-robotics","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/futuristic-robotic-bird-gliding-low-above-water-with-a-trailing-wire.png?id=68024679&width=980","d":"2026-10-02T13:30-03:00","c":["competicoes","humanoides"],"l":0,"to":"Video Friday: Albatross Falls, Spins, Self-Rights, and Sails Away","lg":"en","esp":1,"p":6.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Sua seleção semanal de incríveis vídeos de robôs inclui um braço modular automontável para recuperação de desastres e uso de drones após as enchentes no Nepal"},{"id":"0f4b22002f9ab0","t":"Robot Talk Episódio 164 – Acelerando o aprendizado do robô, com Michelle Lu","r":"Claire conversou com Michelle Lu da Vsim Technology sobre o uso de simulação e inteligência artificial para ensinar novas habilidades aos robôs. Michelle Lu é cofundadora e CEO da Vsim Technology. Anteriormente, ela foi Diretora de Tecnologia de Simulação na NVIDIA, onde ela e seu cofundador criaram o primeiro software ponta a ponta do mundo…","u":"https://robohub.org/robot-talk-episode-164-accelerating-robot-learning-with-michelle-lu/","f":"Robohub","s":"robohub.org","i":"https://robohub.org/wp-content/uploads/2026/10/Michelle-Lu-283x425.png","d":"2026-10-02T08:33-03:00","c":["ia"],"l":0,"to":"Robot Talk Episode 164 – Accelerating robot learning, with Michelle Lu","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"Robohub","mx":1,"rx":"Claire conversou com Michelle Lu, da Vsim Technology, sobre o uso de simulação e inteligência artificial para ensinar novas habilidades aos robôs. Michelle Lu é cofundadora e CEO da Vsim Technology. Anteriormente, ela foi diretora de tecnologia de simulação na NVIDIA, onde ela e seu cofundador criaram a primeira estrutura de aprendizagem por reforço (RL) acelerada por GPU de ponta a ponta do mundo, Isaac Gym, que estabeleceu o modelo de como a RL moderna baseada em simulação acelerada por GPU é executada na robótica. Em 2022, Michelle e seu cofundador deixaram a NVIDIA para criar o Vsim, com o objetivo de resolver as limitações que atormentam a IA robótica baseada em simulação: eficiência, escalabilidade e a lacuna entre o simulador e o real."},{"id":"a9b90ed9dd59c4","t":"Robô do MIT nada na água através de células musculares vivas","r":"Um robô do MIT alimentado por uma única camada de células musculares vivas nadou através de um labirinto aquático, seguindo uma luz na mão de um pesquisador. É lento, minúsculo e está longe de estar pronto para o mar aberto, mas seu design fino pode apontar para máquinas de natação mais macias e baratas. Continue lendo Categoria: Robótica…","u":"https://newatlas.com/robotics/mit-robot-swims-light-living-muscle-cells/","f":"Robotics","s":"newatlas.com","i":"https://assets.newatlas.com/dims4/default/9a75d6b/2147483647/strip/true/crop/1800x1198+0+0/resize/1440x958!/format/webp/quality/90/?url=https%3A%2F%2Fnewatlas-brightspot.s3.ap-southeast-2.amazonaws.com%2F8d%2F0a%2F2c4e524944869787ad1acf136f17%2Fmit-robomuscle-01-press-0.jpg","d":"2026-10-02T22:00-03:00","c":["ia","microrrobos"],"l":0,"to":"MIT robot swims through water via living muscle cells","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"New Atlas","mx":1,"rx":"Um robô do MIT alimentado por uma única camada de células musculares vivas nadou através de um labirinto aquático, seguindo uma luz na mão de um pesquisador. É lento, minúsculo e está longe de estar pronto para o mar aberto, mas seu design fino pode apontar para máquinas de natação mais macias e baratas. O robô tem aproximadamente o tamanho de um chiclete, com células musculares presas a um gel flexível.\nNo projeto anterior da equipe, o gel de fibrina muito macio tendia a enrugar à medida que as células musculares eram puxadas contra ele. Seus pesquisadores dizem que o projeto pode precisar de menos células do que os blocos musculares mais grossos usados ​​em outros robôs biohíbridos. “Atualmente, os robôs biohíbridos do nosso grupo e de outros são construídos a partir de pedaços volumosos e 3D de músculo esquelético cultivado em laboratório que requerem milhões de células para serem fabricados”, diz Raman."}],"2026-10-01":[{"id":"73878f37956bc6","t":"A nova mão do Atlas Robot pode superar designs semelhantes aos humanos","r":"Hoje, a Boston Dynamics está anunciando uma mão redesenhada para seu robô Atlas. A geração anterior podia fazer algumas coisas malucas e sobre-humanas com seus três dedos, mas nunca foi planejada para produção em massa na casa das dezenas ou centenas de milhares. Mudar de hardware de pesquisa para um produto escalável faz com que anteriormente…","u":"https://spectrum.ieee.org/robust-robot-hand","f":"IEEE Spectrum","s":"spectrum.ieee.org","i":"https://spectrum.ieee.org/media-library/close-up-of-a-robotic-hand-with-three-fingers-and-a-thumb-making-a-gesture-similar-to-the-sign-of-the-horns.jpg?id=67879402&width=980","d":"2026-10-01T11:40-03:00","c":["humanoides"],"l":1,"to":"Atlas Robot’s New Hand May Outperform Humanlike Designs","lg":"en","esp":1,"p":12.4,"cr":3,"cv":"IEEE Spectrum","mx":1,"rx":"Três dedos e um polegar com 13 graus de liberdade é o que a Boston Dynamics diz que sua mão precisa – para fazer quase tudo."},{"id":"948beaea7c564d","t":"Esta IA alimentada por luz pode detectar deepfakes com quase 98% de precisão","r":"Pesquisadores da UCLA construíram um sistema de IA que usa luz para analisar mais de uma dúzia de vídeos simultaneamente, detectando deepfakes com quase 98% de precisão. Sua velocidade, baixa demanda de energia e resistência a ataques podem torná-lo uma ferramenta poderosa para rastrear a crescente enxurrada de vídeos gerados por IA.","u":"https://www.sciencedaily.com/releases/2026/09/260929053534.htm","f":"Robotics Research News -- ScienceDaily","s":"sciencedaily.com","i":"https://www.sciencedaily.com/images/1920/optical-ai-technology-that-detects-deepfake-videos.webp","d":"2026-10-01T10:03-03:00","c":["ia"],"l":0,"to":"This light-powered AI can spot deepfakes with nearly 98% accuracy","lg":"en","esp":1,"p":5.6,"cr":3,"cv":"ScienceDaily","mx":1,"rx":"Pesquisadores da Universidade da Califórnia, em Los Angeles (UCLA), criaram um novo processador óptico-neural que usa luz para ajudar a identificar vídeos deepfake com rapidez e precisão. Ao contrário dos sistemas convencionais que normalmente examinam vídeos um após o outro usando hardware digital, a tecnologia UCLA pode analisar 15 ou mais fluxos de vídeo ao mesmo tempo. Isto permite que muitos vídeos sejam avaliados simultaneamente durante uma única passagem óptica, em vez de exigir que cada um se mova separadamente através de um pipeline de processamento digital convencional.\nEm experimentos utilizando luz visível, o processador examinou 15 vídeos Celeb-DF simultaneamente durante cada passagem óptica. Os pesquisadores também levaram o sistema ainda mais longe, aumentando sua capacidade para 18 vídeos em uma única passagem óptica."}]};
